insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('AL', 'Under Alabama''s Graduated Driver License (GDL) restrictions, a 16-year-old with a restricted license may not operate a vehicle between midnight and 6:00 a.m. unless accompanied by:', '["A parent, legal guardian, or licensed driver 21 or older", "Any licensed passenger over the age of 18", "A sibling who has held their license for at least one year", "A certified driver''s education instructor only"]'::jsonb, 0, 'Alabama''s GDL law prohibits 16-year-old drivers from driving between midnight and 6 a.m. unless accompanied by a parent, legal guardian, or a person 21 or older designated by the parent.', 'defensive_driving', 'hard', 'drivesight-al-25', true),
  ('AL', 'You arrive at an uncontrolled intersection at the exact same time as a vehicle to your right. Who has the legal right-of-way?', '["The vehicle on the left", "The vehicle on the right", "The vehicle traveling at a faster speed", "The larger of the two vehicles"]'::jsonb, 1, 'At uncontrolled intersections, the driver on the left must yield the right-of-way to the vehicle on the right when both arrive simultaneously.', 'right_of_way', 'medium', 'drivesight-al-25', true),
  ('AL', 'A school bus is stopped on a five-lane highway (four travel lanes and a central two-way turn lane), and its red lights are flashing. If you are traveling in the opposite direction, are you required to stop?', '["Yes, all traffic must stop regardless of direction", "No, vehicles traveling in the opposite direction may proceed", "Yes, but you may roll past at 15 mph", "No, unless the bus driver manually signals you to stop"]'::jsonb, 0, 'In Alabama, a center turn lane does not constitute a divided highway. All traffic on a multi-lane road without a physical barrier must stop for a school bus with flashing red lights.', 'school_zones', 'hard', 'drivesight-al-25', true),
  ('AL', 'For a driver under the age of 21 in Alabama, what blood alcohol concentration (BAC) threshold constitutes legal intoxication?', '["0.08% or higher", "0.05% or higher", "0.02% or higher", "Any measurable amount above 0.00%"]'::jsonb, 2, 'Alabama has a zero-tolerance law for underage drinking and driving. A BAC of 0.02% or higher is considered legally intoxicated for drivers under 21.', 'dui_alcohol_laws', 'medium', 'drivesight-al-25', true),
  ('AL', 'Heavy rain has just started to fall on a hot afternoon. Why are the roads particularly hazardous during the first 10 to 15 minutes of the storm?', '["Water levels rise rapidly in adjacent drainage ditches", "Oil and dust on the pavement mix with the rain, creating a slick surface", "Other drivers consistently speed up to reach their destinations faster", "Brake pads absorb water instantly, causing immediate brake failure"]'::jsonb, 1, 'During the initial minutes of rain, accumulated oil, dirt, and rubber dust mix with water to create an extremely slippery, soap-like layer on the road surface.', 'weather_driving', 'easy', 'drivesight-al-25', true),
  ('AL', 'When following a motorcycle on the highway, it is crucial to increase your following distance primarily because:', '["Motorcycles can stop much faster than standard passenger vehicles", "Motorcycles are legally allowed to brake test following drivers", "Motorcycles frequently stall in high-speed traffic conditions", "Motorcycles require twice the width of a standard lane to maneuver safely"]'::jsonb, 0, 'Motorcycles are lighter and can decelerate much faster than cars. Leaving extra following distance gives you adequate time to react if the motorcyclist stops suddenly.', 'motorcycle_awareness', 'medium', 'drivesight-al-25', true),
  ('AL', 'A blind pedestrian is standing at a corner waiting to cross, identifiable by a white cane. As you approach the crosswalk, your legal obligation is to:', '["Honk your horn lightly to let them know a vehicle is present", "Yield the right-of-way and come to a complete stop", "Proceed slowly through the crosswalk if they haven''t stepped off the curb yet", "Roll down your window and direct them verbally to cross safely"]'::jsonb, 1, 'Drivers must always yield the right-of-way to pedestrians carrying a white cane or using a guide dog, coming to a complete stop to ensure their safety.', 'pedestrian_safety', 'easy', 'drivesight-al-25', true),
  ('AL', 'Unless signage indicates otherwise, what is the statutory speed limit within an Alabama urban district?', '["25 mph", "30 mph", "35 mph", "45 mph"]'::jsonb, 1, 'According to Alabama''s basic speed laws, the speed limit in an urban district is 30 mph unless otherwise posted.', 'speed_limits', 'medium', 'drivesight-al-25', true),
  ('AL', 'Before pulling out to pass a slower vehicle on a two-lane country road, what sequence of actions should you take?', '["Tailgate briefly to signal your intent to the driver ahead", "Flash your high beams rapidly to clear oncoming traffic", "Check your mirrors, physically check your blind spot, and activate your turn signal", "Accelerate aggressively before moving into the oncoming lane"]'::jsonb, 2, 'Safe passing requires comprehensive awareness. You must check your mirrors for vehicles behind you, look over your shoulder to check your blind spot, and signal your intent before changing lanes.', 'passing_rules', 'easy', 'drivesight-al-25', true),
  ('AL', 'Fines for moving traffic violations committed in an active Alabama highway work zone are:', '["The same as standard violations", "Doubled when construction workers are present", "Tripled automatically", "Handled in federal court instead of state jurisdiction"]'::jsonb, 1, 'To protect highway workers, Alabama law mandates that fines for traffic violations are doubled when committed in an active construction zone with workers present.', 'work_zones', 'medium', 'drivesight-al-25', true),
  ('AL', 'You are approaching a complex intersection where the traffic signal is displaying a flashing yellow light. How should you navigate this intersection?', '["Treat it as a four-way stop and yield to the right", "Slow down, scan for cross traffic, and proceed with caution", "Come to a complete stop and wait for the light to turn solid green", "Accelerate to clear the intersection as quickly as possible"]'::jsonb, 1, 'A flashing yellow light indicates that you should slow down and proceed through the intersection with heightened caution, being prepared to yield if necessary.', 'traffic_signals', 'easy', 'drivesight-al-25', true),
  ('AL', 'While driving on I-65, you realize you have just missed your intended exit. Your safest and legal course of action is to:', '["Carefully back up on the right shoulder with your hazard lights on", "Make a U-turn through an opening in the grassy median", "Continue driving to the next available exit and turn around safely", "Stop in the right travel lane and wait for a gap to reverse"]'::jsonb, 2, 'Reversing or making U-turns on the interstate is extremely dangerous and illegal. If you miss your exit, you must always continue to the next one.', 'freeway_driving', 'easy', 'drivesight-al-25', true),
  ('AL', 'Under Alabama''s distracted driving laws, the act of writing, sending, or reading a text message while operating a motor vehicle is:', '["Permitted only for drivers over the age of 18", "Strictly illegal for all drivers on public roads", "Legal as long as the phone remains mounted on the dashboard", "Permitted only when stopped at a red traffic light"]'::jsonb, 1, 'Alabama law prohibits all drivers, regardless of age, from reading, writing, or sending a text message while operating a vehicle on a public road.', 'distracted_driving', 'easy', 'drivesight-al-25', true),
  ('AL', 'To maintain a safe following distance and avoid tailgating under ideal driving conditions, Alabama recommends utilizing:', '["The rule of one car length for every 10 mph of speed", "The ''two-second rule'' behind the vehicle in front of you", "A fixed distance of 15 feet at all times", "A distance of no less than half a mile on highways"]'::jsonb, 1, 'The ''two-second rule'' is the recommended minimum safe following distance in ideal conditions. In poor weather, this distance should be increased.', 'defensive_driving', 'medium', 'drivesight-al-25', true),
  ('AL', 'An ambulance with flashing emergency lights and an active siren is approaching rapidly from behind. Your immediate reaction should be to:', '["Maintain your current speed and lane position", "Speed up to stay ahead of the ambulance", "Pull over to the right edge of the roadway and stop completely", "Move into the left lane and slow down significantly"]'::jsonb, 2, 'When an emergency vehicle approaches with active signals, you must yield the right-of-way by pulling as close as possible to the right-hand edge of the road and stopping.', 'emergency_vehicles', 'easy', 'drivesight-al-25', true),
  ('AL', 'When approaching a railroad crossing where the warning gates have been lowered and lights are flashing, Alabama law requires you to stop within what distance of the nearest rail?', '["5 to 10 feet", "15 to 50 feet", "50 to 100 feet", "No less than 100 feet away"]'::jsonb, 1, 'You must stop between 15 and 50 feet from the nearest rail of a railroad crossing whenever a train is approaching, signals are flashing, or gates are lowered.', 'railroad_crossings', 'hard', 'drivesight-al-25', true),
  ('AL', 'You are parking your vehicle facing downhill on a steep street bordered by a physical curb. To prevent your car from rolling into traffic, your front wheels should be:', '["Positioned perfectly straight", "Turned sharply away from the curb", "Turned sharply toward the curb", "Resting directly on top of the curb edge"]'::jsonb, 2, 'When parking downhill with a curb, turning your front wheels toward the curb ensures that if the brakes fail, the vehicle will roll into the curb and stop, rather than into traffic.', 'parking', 'medium', 'drivesight-al-25', true),
  ('AL', 'Blind spots are areas around your vehicle that cannot be seen using your standard mirrors. To verify these areas are clear before executing a lane change, you must:', '["Glance briefly over your shoulder in the direction you plan to move", "Rely entirely on the panoramic view of your rearview mirror", "Tap your horn to alert vehicles that might be hiding there", "Swerve slightly to get a different mirror angle"]'::jsonb, 0, 'Mirrors leave blind spots on the left and right rear of your vehicle. The only way to ensure these areas are clear is to physically turn your head and glance over your shoulder.', 'lane_changes', 'easy', 'drivesight-al-25', true),
  ('AL', 'A solid pennant-shaped yellow sign placed strategically on the left side of a two-lane highway serves to indicate:', '["An active school crossing ahead", "The beginning of a no passing zone", "A sharp, dangerous curve to the left", "The point where a divided highway ends"]'::jsonb, 1, 'The yellow, pennant-shaped sign is exclusively used to mark a ''No Passing Zone'' and is always placed on the left side of the road facing the driver.', 'road_signs', 'medium', 'drivesight-al-25', true),
  ('AL', 'When entering a highway from a designated acceleration lane, your primary objective to ensure a safe transition should be to:', '["Stop completely at the end of the ramp and wait for an opening", "Match the speed of highway traffic and merge seamlessly when a safe gap appears", "Enter the highway at a cautious 25 mph and gradually build speed", "Merge immediately, forcing other drivers to change lanes or brake"]'::jsonb, 1, 'The acceleration lane is designed to let you build up to the speed of highway traffic before merging. Stopping or entering too slowly creates a severe collision hazard.', 'merging', 'easy', 'drivesight-al-25', true),
  ('AL', 'You are preparing to make a left turn at an intersection with a solid green light, but there is no green arrow. Oncoming traffic is approaching. What is the correct procedure?', '["Yield to oncoming traffic and execute the turn only when there is a safe gap", "Turn immediately, as the solid green light grants you the absolute right-of-way", "Pull fully into the center of the intersection and wait for the light to turn red", "Flash your high beams to alert oncoming traffic before turning in front of them"]'::jsonb, 0, 'A solid green light means you may turn left, but you must yield the right-of-way to all oncoming traffic and pedestrians. You do not have a protected turn without a green arrow.', 'intersections', 'medium', 'drivesight-al-25', true),
  ('AL', 'A continuous solid double yellow line running down the center of a two-way roadway means:', '["Passing is permitted for both directions of traffic if clear", "Passing is strictly prohibited for traffic traveling in both directions", "The lane is designated for left turns only", "Passing is allowed only during daylight hours"]'::jsonb, 1, 'Double solid yellow lines separate traffic moving in opposite directions and indicate that neither side is allowed to pass.', 'road_signs', 'easy', 'drivesight-al-25', true),
  ('AL', 'When approaching an intersection where a completely blind pedestrian is attempting to cross without a marked crosswalk, what must you do?', '["Yield the right-of-way since pedestrians have the right of way even outside marked lines", "Proceed without stopping, as crosswalk laws only apply to painted lines", "Honk repeatedly to warn them they are out of the designated zone", "Stop and physically assist them across the street"]'::jsonb, 0, 'Drivers must always yield the right-of-way to completely or partially blind pedestrians carrying a white cane or using a guide dog, regardless of whether they are in a marked crosswalk.', 'pedestrian_safety', 'hard', 'drivesight-al-25', true),
  ('AL', 'Hydroplaning occurs when a layer of water builds up between your tires and the road surface. If you feel your vehicle begin to hydroplane, you should:', '["Slam on your brakes immediately to regain traction", "Jerk the steering wheel in the opposite direction of the skid", "Ease your foot off the accelerator and steer straight until you regain control", "Accelerate slightly to push the water out from under the tires"]'::jsonb, 2, 'Braking or turning suddenly can cause you to completely lose control during hydroplaning. Easing off the gas and keeping the wheel straight allows the vehicle to naturally slow and tires to reconnect with the road.', 'weather_driving', 'medium', 'drivesight-al-25', true),
  ('AL', 'In Alabama, what is the mandatory penalty for a first-offense DUI (Driving Under the Influence) conviction?', '["A simple warning and mandatory defensive driving class", "Immediate revocation of your license for a minimum of 5 years", "A fine of $600 to $2,100 and a 90-day license suspension", "Permanent confiscation of your vehicle"]'::jsonb, 2, 'A first DUI conviction in Alabama carries severe penalties, including a $600 to $2,100 fine, up to a year in jail, and a 90-day suspension of driving privileges.', 'dui_alcohol_laws', 'hard', 'drivesight-al-25', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('AK', 'When driving in Alaska during the winter months, what is the most effective way to recover if your vehicle begins to skid on an icy road?', '["Slam on the brakes to engage the ABS system immediately", "Steer in the direction you want the front of the vehicle to go", "Accelerate slightly to shift weight to the rear tires", "Oversteer in the opposite direction of the skid"]'::jsonb, 1, 'If your vehicle begins to skid on ice, take your foot off the gas and carefully steer in the direction you want the front of the vehicle to go. Avoid slamming on the brakes, which can lock the wheels and make the skid worse.', 'weather_driving', 'medium', 'drivesight-ak-15', true),
  ('AK', 'Under Alaska law, studded snow tires are legally permitted on vehicles during which general timeframe?', '["Year-round for all vehicles", "Mid-September through early May", "Only during declared winter weather emergencies", "November 1st through March 1st"]'::jsonb, 1, 'Studded tires are legally allowed in Alaska from September 15th to May 1st (or May 15th for areas north of 60 degrees North Latitude) to prevent severe damage to paved roads during warmer months.', 'weather_driving', 'hard', 'drivesight-ak-15', true),
  ('AK', 'You are driving on a rural Alaskan highway and spot a moose standing near the shoulder. What is the safest course of action?', '["Honk your horn continuously to scare it away", "Maintain your speed and swerve into the oncoming lane to pass", "Slow down significantly and be prepared to stop", "Flash your high beams rapidly to blind the animal"]'::jsonb, 2, 'Moose are unpredictable and top-heavy. Striking one can be fatal for the occupants of the vehicle. You should always slow down and prepare to stop if you see wildlife near the roadway.', 'defensive_driving', 'easy', 'drivesight-ak-15', true),
  ('AK', 'Unless otherwise posted by road signs, what is the maximum statutory speed limit on Alaskan state highways?', '["45 mph", "55 mph", "65 mph", "75 mph"]'::jsonb, 1, 'The maximum speed limit on state highways in Alaska is 55 mph unless signs specifically indicate a higher speed limit, such as 65 mph on certain interstates.', 'speed_limits', 'medium', 'drivesight-ak-15', true),
  ('AK', 'Alaska''s ''Implied Consent'' law means that by operating a motor vehicle on public roads, you automatically agree to:', '["Allow police to search your vehicle without a warrant at any time", "Submit to a chemical test for alcohol or drugs if lawfully arrested for DUI", "Pay all traffic fines within 30 days of receiving a citation", "Carry liability insurance for any passengers in your car"]'::jsonb, 1, 'Implied consent means that if you are arrested for driving under the influence, you have already consented to take a breath or blood test to determine your blood alcohol concentration.', 'dui_alcohol_laws', 'hard', 'drivesight-ak-15', true),
  ('AK', 'You are approaching a stopped school bus with its red lights flashing on an undivided two-lane road in Anchorage. What are you legally required to do?', '["Slow down to 15 mph and pass with caution", "Stop only if children are actively crossing the street", "Stop completely and wait until the red lights stop flashing", "Honk your horn before pulling around the left side of the bus"]'::jsonb, 2, 'On an undivided roadway, all traffic traveling in both directions must come to a complete stop for a school bus with flashing red lights and an extended stop arm.', 'school_zones', 'easy', 'drivesight-ak-15', true),
  ('AK', 'In Alaska, the act of reading or typing a text message while operating a moving motor vehicle is considered:', '["A minor traffic infraction resulting in a warning", "Legal as long as the phone is held below the steering wheel", "A serious misdemeanor crime that carries strict penalties", "Only illegal for drivers under the age of 21"]'::jsonb, 2, 'Alaska has some of the strictest distracted driving laws in the country. Texting while driving is a misdemeanor offense, not just a traffic ticket, and carries severe fines.', 'distracted_driving', 'medium', 'drivesight-ak-15', true),
  ('AK', 'An emergency vehicle with flashing lights and an active siren is approaching from behind on a two-lane road. You must:', '["Maintain your speed until you find a designated pull-out area", "Pull over to the right edge of the roadway and stop completely", "Move to the left lane to give them room to pass on the right", "Accelerate to stay ahead of the emergency vehicle"]'::jsonb, 1, 'When an emergency vehicle is approaching with lights and sirens, you must immediately yield the right-of-way by pulling as far to the right as possible and coming to a complete stop.', 'emergency_vehicles', 'easy', 'drivesight-ak-15', true),
  ('AK', 'Alaska law requires drivers to turn on their vehicle''s headlights during which specific times?', '["Only when driving on unpaved or gravel roads", "From a half-hour after sunset to a half-hour before sunrise", "Whenever the vehicle is traveling over 45 mph", "Only between the hours of 10:00 PM and 4:00 AM"]'::jsonb, 1, 'Headlights must be used from a half-hour after sunset until a half-hour before sunrise, or at any other time when visibility is limited and you cannot see clearly for 1,000 feet.', 'weather_driving', 'medium', 'drivesight-ak-15', true),
  ('AK', 'When parking your vehicle facing uphill on a street with a defined physical curb, which way should you turn your front steering wheels?', '["Straight ahead to keep the steering column locked", "Sharply toward the curb", "Sharply away from the curb", "Parallel to the centerline of the road"]'::jsonb, 2, 'When parking uphill with a curb, turn your wheels away from the curb. If the brakes fail, the vehicle will roll backward, and the back of the front tire will catch the curb, stopping the car.', 'parking', 'medium', 'drivesight-ak-15', true),
  ('AK', 'When driving behind an active snowplow clearing an Alaskan highway, what is the safest and recommended procedure?', '["Pass the snowplow quickly on the right shoulder", "Tailgate the plow closely to take advantage of the cleared track", "Stay at least 200 feet behind and avoid passing unless absolutely necessary", "Flash your high beams until the plow pulls over to let you pass"]'::jsonb, 2, 'Snowplows create whiteout conditions and drop anti-icing chemicals. You should maintain a safe following distance of at least 200 feet and never attempt to pass an active plow.', 'passing_rules', 'hard', 'drivesight-ak-15', true),
  ('AK', 'When preparing to enter a multi-lane roundabout intersection, which vehicles have the legal right-of-way?', '["Vehicles entering from the right", "Traffic already circulating inside the roundabout", "Commercial trucks and large SUVs", "Vehicles attempting to exit the roundabout"]'::jsonb, 1, 'Drivers entering a roundabout must always yield the right-of-way to vehicles, bicyclists, and pedestrians already circulating inside the roundabout.', 'intersections', 'medium', 'drivesight-ak-15', true),
  ('AK', 'A continuous solid double yellow line running down the center of the roadway indicates that:', '["Passing is permitted only for the lane with a broken line", "The lane is designated for left turns and U-turns only", "Passing is strictly prohibited for traffic traveling in both directions", "You are entering a designated school zone"]'::jsonb, 2, 'A solid double yellow line separates traffic moving in opposite directions. Neither side is permitted to cross the double lines to pass another vehicle.', 'lane_changes', 'easy', 'drivesight-ak-15', true),
  ('AK', 'Under ideal dry conditions, the recommended following distance is two seconds. On packed snow or icy roads, you should increase this distance to at least:', '["3 to 4 seconds", "8 to 10 seconds", "15 to 20 seconds", "One full mile"]'::jsonb, 1, 'Stopping distances increase exponentially on ice and snow. You should increase your following distance to at least 8 to 10 seconds to allow for safe reaction and braking time.', 'defensive_driving', 'medium', 'drivesight-ak-15', true),
  ('AK', 'When approaching a railroad crossing where the warning gates have been lowered and red lights are flashing, you must stop your vehicle:', '["Directly on the tracks to wait for the train", "Between 15 and 50 feet from the nearest rail", "At least 100 feet away from the crossing", "Only if you can physically see the train approaching"]'::jsonb, 1, 'State law requires drivers to stop between 15 and 50 feet from the nearest rail at a railroad crossing when flashing red lights, lowered gates, or a flagger warn of an approaching train.', 'railroad_crossings', 'hard', 'drivesight-ak-15', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('AZ', 'You are driving on an Arizona highway and suddenly encounter a dense dust storm (haboob) that drops visibility to zero. What is the safest and legally recommended course of action?', '["Turn on your hazard lights and slow down to 15 mph", "Pull completely off the pavement, turn off all lights, and take your foot off the brake", "Stop immediately in your travel lane and activate your high beams", "Maintain your speed but sound your horn continuously until you exit the storm"]'::jsonb, 1, 'In an Arizona dust storm, you must pull completely off the roadway, turn off all vehicle lights (including hazard lights), set the emergency brake, and take your foot off the brake pedal so other drivers don''t follow your tail lights and rear-end you.', 'weather_driving', 'hard', 'drivesight-az-12', true),
  ('AZ', 'In Arizona, driving across the ''gore area'' on a freeway is illegal and heavily fined. What is the gore area?', '["The designated emergency pull-off zone on steep mountain grades", "The far-left High Occupancy Vehicle (HOV) lane during restricted hours", "The painted triangular space between a highway travel lane and an exit/entrance ramp", "The unpaved dirt shoulder on the right side of the interstate"]'::jsonb, 2, 'The gore area is the triangular painted area between a freeway and an exit or entrance ramp. Crossing over this solid white V-shaped area is dangerous and strictly prohibited in Arizona.', 'freeway_driving', 'medium', 'drivesight-az-12', true),
  ('AZ', 'Under Arizona''s Graduated Driver License laws, a teen with a Class G license is restricted from driving between what hours during their first six months, unless accompanied by a parent or guardian?', '["10:00 PM and 5:00 AM", "Midnight and 5:00 AM", "11:00 PM and 6:00 AM", "9:00 PM and 6:00 AM"]'::jsonb, 1, 'During the first six months of holding a Class G graduated license in Arizona, a teen may not drive between midnight and 5:00 a.m. unless accompanied by a parent, legal guardian, or a certified driving instructor.', 'defensive_driving', 'hard', 'drivesight-az-12', true),
  ('AZ', 'When approaching a standard school crossing zone in Arizona, the mandated speed limit is:', '["15 mph", "20 mph", "25 mph", "10 mph"]'::jsonb, 0, 'The speed limit approaching a school crosswalk in Arizona is 15 mph. You must adhere to this limit whenever the yellow crosswalk signs are displayed or flashing.', 'school_zones', 'easy', 'drivesight-az-12', true),
  ('AZ', 'Arizona law categorizes a DUI as an ''Extreme DUI'' when a driver''s Blood Alcohol Concentration (BAC) reaches or exceeds:', '["0.08%", "0.10%", "0.15%", "0.20%"]'::jsonb, 2, 'While standard DUI in Arizona is 0.08%, an ''Extreme DUI'' is charged when a driver has a BAC of 0.15% or higher, which carries significantly harsher jail times and fines.', 'dui_alcohol_laws', 'medium', 'drivesight-az-12', true),
  ('AZ', 'You are driving on a two-lane road and a vehicle behind you is tailgating aggressively, flashing their lights to pass. What is the best defensive driving technique?', '["Tap your brakes rapidly to warn them to back off", "Accelerate to match the speed they wish to travel", "Move slightly to the right side of your lane and let them pass", "Turn on your hazard lights and stay in the center of your lane"]'::jsonb, 2, 'If someone is tailgating you and wants to pass, you should move slightly to the right side of your lane and avoid speeding up, allowing them to pass safely and reducing the danger to yourself.', 'defensive_driving', 'easy', 'drivesight-az-12', true),
  ('AZ', 'In Arizona, the ''Move Over'' law requires drivers approaching a stationary emergency vehicle with flashing lights on a multi-lane highway to:', '["Stop completely until an officer signals you to proceed", "Move into a lane that is not immediately adjacent to the emergency vehicle", "Honk your horn to acknowledge their presence and maintain speed", "Accelerate past the incident quickly to clear the area"]'::jsonb, 1, 'Arizona''s Move Over law mandates that you shift over one lane away from any stationary emergency, maintenance, or stranded vehicle with flashing lights. If you cannot move over safely, you must significantly reduce your speed.', 'emergency_vehicles', 'medium', 'drivesight-az-12', true),
  ('AZ', 'Unless otherwise posted by road signs, what is the speed limit in an Arizona business or residential district?', '["20 mph", "25 mph", "30 mph", "35 mph"]'::jsonb, 1, 'According to Arizona''s basic speed law, the maximum speed in residential and business districts is 25 mph unless a different speed is posted.', 'speed_limits', 'easy', 'drivesight-az-12', true),
  ('AZ', 'You are preparing to make a right turn at a red light. After coming to a complete stop, you notice a pedestrian stepping into the crosswalk. Who has the right-of-way?', '["You have the right-of-way because you are turning", "The pedestrian has the right-of-way and you must wait until they cross safely", "Whoever entered the intersection first has the right-of-way", "You may proceed if you can squeeze past the pedestrian without hitting them"]'::jsonb, 1, 'Even when making a legal right turn on red, you must yield the right-of-way to all pedestrians crossing in the intersection.', 'pedestrian_safety', 'easy', 'drivesight-az-12', true),
  ('AZ', 'Under the ''Stupid Motorist Law'' in Arizona, you may be held financially responsible for the cost of your own rescue if you:', '["Run out of gas on a rural interstate highway", "Deliberately drive past barricades into a flooded wash or roadway", "Fail to carry a spare tire and require a tow truck", "Drive off a mountain road due to excessive speeding"]'::jsonb, 1, 'Arizona''s ''Stupid Motorist Law'' states that any driver who bypasses barricades to enter a flooded stretch of roadway and requires emergency extraction can be billed for the cost of the rescue operations.', 'weather_driving', 'medium', 'drivesight-az-12', true),
  ('AZ', 'A solid yellow line next to a broken yellow line down the center of the road indicates that passing is:', '["Prohibited for vehicles traveling in both directions", "Permitted for vehicles adjacent to the solid line", "Permitted for vehicles adjacent to the broken line", "Permitted only for motorcycles and emergency vehicles"]'::jsonb, 2, 'When there is a solid yellow line next to a broken yellow line, passing is only permitted for the drivers traveling on the side with the broken line, provided the way is clear.', 'passing_rules', 'easy', 'drivesight-az-12', true),
  ('AZ', 'When sharing the road with a commercial semi-truck, what is the most dangerous area around the truck, often referred to as the ''No-Zone''?', '["Directly in front of the truck''s grill", "Directly behind the truck''s trailer", "The blind spots on the sides, rear, and front of the truck", "The lane to the far left of the truck"]'::jsonb, 2, 'The ''No-Zone'' refers to the large blind spots located immediately in front of, behind, and along the sides of commercial trucks. If you cannot see the truck''s mirrors, the driver cannot see you.', 'defensive_driving', 'medium', 'drivesight-az-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('AR', 'Under Arkansas law, a driver must automatically turn on their vehicle''s headlights whenever:', '["Driving over the speed of 55 mph", "The vehicle''s windshield wipers are in use due to weather", "Entering any marked construction or work zone", "Driving on an unpaved county road"]'::jsonb, 1, 'Arkansas law requires that a driver turn on their headlights whenever their windshield wipers are in use to clear rain, snow, or other precipitation.', 'weather_driving', 'easy', 'drivesight-ar-10', true),
  ('AR', 'On a multi-lane highway in Arkansas, the far left lane is legally designated for:', '["Vehicles traveling exactly at the posted speed limit", "Commercial semi-trucks and buses only", "Passing slower traffic and preparing for left turns", "Drivers utilizing cruise control systems"]'::jsonb, 2, 'Arkansas enforces a ''keep right'' law. The left lane on multi-lane highways is legally intended only for passing slower vehicles or preparing to make a left turn.', 'lane_changes', 'medium', 'drivesight-ar-10', true),
  ('AR', 'You are driving on an Arkansas highway divided by a 20-foot wide grass median. A school bus traveling in the opposite direction has stopped with its red lights flashing. What must you do?', '["Come to a complete stop and wait for the lights to turn off", "Slow to 15 mph and proceed cautiously past the bus", "You are not required to stop because the highway is divided by a median", "Stop only if children are actively crossing the grass median"]'::jsonb, 2, 'In Arkansas, if a highway is divided by a physical barrier or an unpaved median strip at least 20 feet wide, drivers traveling in the opposite direction of a stopped school bus do not have to stop.', 'school_zones', 'hard', 'drivesight-ar-10', true),
  ('AR', 'In Arkansas, ''Paul''s Law'' severely restricts distracted driving. Which of the following is true regarding cell phone use while driving?', '["Texting is illegal for all drivers, regardless of age", "Drivers over 21 may text if stopped at a red light", "Drivers ages 18-20 may use a handheld phone for any reason", "Only drivers with a learner''s permit are banned from texting"]'::jsonb, 0, 'Under ''Paul''s Law'' in Arkansas, writing, typing, reading, or sending text messages on a wireless device is strictly illegal for all drivers, regardless of age or experience level.', 'distracted_driving', 'easy', 'drivesight-ar-10', true),
  ('AR', 'When approaching a flashing red traffic light at an intersection, your legal obligation is to:', '["Slow down and yield to cross traffic without coming to a full stop", "Treat the signal as a stop sign, stopping completely before proceeding safely", "Treat the signal as a yield sign, only stopping if pedestrians are present", "Wait until the light turns solid green to proceed"]'::jsonb, 1, 'A flashing red traffic light has the exact same legal meaning as a stop sign. You must come to a complete stop, yield the right-of-way, and proceed only when it is safe to do so.', 'traffic_signals', 'easy', 'drivesight-ar-10', true),
  ('AR', 'According to Arkansas laws regarding railroad crossings, a driver must stop their vehicle within what distance from the nearest track when a train is approaching?', '["No closer than 5 feet and no further than 20 feet", "No closer than 15 feet and no further than 50 feet", "Exactly 30 feet from the nearest rail", "Only behind the solid white stop line"]'::jsonb, 1, 'When approaching a railroad crossing with active warnings or a visible train, Arkansas law requires you to stop within 50 feet, but no less than 15 feet, from the nearest rail.', 'railroad_crossings', 'medium', 'drivesight-ar-10', true),
  ('AR', 'You are driving on an unpaved county dirt road and approach an intersection with a paved state highway. Who has the right-of-way?', '["The vehicle on the unpaved road", "The vehicle on the paved state highway", "The vehicle that arrives at the intersection first", "The vehicle making a right turn"]'::jsonb, 1, 'When entering a paved thoroughfare from an unpaved dirt or gravel road, the vehicle entering from the unpaved road must yield the right-of-way to traffic on the paved road.', 'right_of_way', 'medium', 'drivesight-ar-10', true),
  ('AR', 'For drivers under the legal drinking age of 21 in Arkansas, the state''s ''Zero Tolerance'' law considers it illegal to drive with a Blood Alcohol Concentration (BAC) of:', '["0.08% or higher", "0.05% or higher", "0.02% or higher", "0.10% or higher"]'::jsonb, 2, 'Arkansas has a strict Zero Tolerance law for underage drinking and driving. A BAC of 0.02% or greater is grounds for an underage DUI charge.', 'dui_alcohol_laws', 'hard', 'drivesight-ar-10', true),
  ('AR', 'When parallel parking your vehicle along an Arkansas street, your wheels must be positioned:', '["More than 24 inches from the right curb", "Resting directly on top of the curb line", "No more than 18 inches from the right curb", "Turned sharply to the left at all times"]'::jsonb, 2, 'To properly parallel park and ensure you are not obstructing traffic, your vehicle''s wheels must be positioned parallel to and no more than 18 inches from the curb.', 'parking', 'medium', 'drivesight-ar-10', true),
  ('AR', 'A solid white line separating traffic traveling in the same direction signifies that:', '["Lane changes are encouraged to pass slower traffic", "The lane is designated for High Occupancy Vehicles (HOV)", "Lane changes are discouraged, and you should stay in your lane", "You are entering a designated school zone"]'::jsonb, 2, 'While broken white lines allow passing, a solid white line between lanes of traffic moving in the same direction indicates that lane changes are hazardous and strongly discouraged.', 'road_signs', 'easy', 'drivesight-ar-10', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('CA', 'What does an octagonal red sign mean?', '["Yield to cross traffic", "Stop completely, then go when safe", "Merge left", "No parking anytime"]'::jsonb, 1, 'Octagon signs are stop signs; you must stop before proceeding.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A yellow pennant-shaped sign on the left side of the road means:', '["No passing zone for traffic in both directions", "No passing zone for traffic traveling in your direction", "School crossing ahead", "Lane ends ahead"]'::jsonb, 1, 'The pennant marks the start of a no-passing zone for your direction of travel.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'An orange sign with black letters usually indicates:', '["A recreation area", "Road construction or maintenance", "A hospital zone", "A scenic overlook"]'::jsonb, 1, 'Orange signs warn of work zones and temporary traffic control.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A round yellow sign with an X and RR means:', '["Rest area ahead", "Railroad crossing ahead", "Roundabout ahead", "Road closed"]'::jsonb, 1, 'This advance warning sign alerts drivers to an upcoming railroad crossing.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A fluorescent yellow-green sign is often used for:', '["Freeway exits", "School zones and pedestrian areas", "Parking restrictions", "Toll plazas"]'::jsonb, 1, 'This color improves visibility for school and pedestrian warnings.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A red circle with a slash over a symbol means:', '["The action shown is required", "The action shown is prohibited", "Warning only", "Services available"]'::jsonb, 1, 'A red slash means the illustrated action is not allowed.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A diamond-shaped yellow sign warns of:', '["Regulatory rules", "Hazards or changing road conditions ahead", "Services", "Motorist services"]'::jsonb, 1, 'Diamond yellow signs are general warning signs.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A white rectangular sign typically shows:', '["Warnings", "Regulatory rules such as speed limits", "Construction zones", "Scenic routes"]'::jsonb, 1, 'White rectangles usually communicate laws and regulations.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A green guide sign on a freeway usually provides:', '["Warnings", "Direction and distance information", "Prohibited actions", "School zone limits"]'::jsonb, 1, 'Green signs help drivers navigate routes and exits.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A blue sign at a rest area indicates:', '["Construction", "Motorist services and information", "No trucks", "Hospital zone"]'::jsonb, 1, 'Blue signs point to services like food, fuel, and lodging.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Two solid yellow lines in the center of a two-lane road mean:', '["Passing allowed both ways", "Passing is not allowed in either direction", "Passing allowed only at night", "Center lane for turning only"]'::jsonb, 1, 'Double solid yellow lines prohibit passing from either direction.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A broken yellow line on your side means:', '["You may pass when safe", "No passing ever", "Stop required", "Two-way left turn lane"]'::jsonb, 0, 'A broken yellow line on your side permits passing when safe.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A white curb painted red means:', '["Loading zone only", "No stopping, standing, or parking", "Passenger pickup only", "Electric vehicle charging"]'::jsonb, 1, 'Red curbs prohibit stopping except for buses in marked zones.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A sign showing a curved arrow with a speed number advises:', '["Minimum speed in a curve", "Recommended safe speed for the curve", "Maximum legal speed always", "Truck route only"]'::jsonb, 1, 'Advisory speed signs suggest a safe speed for the curve.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A triangular sign pointing down means:', '["Yield", "Stop", "Merge", "Detour"]'::jsonb, 0, 'An inverted triangle is a yield sign.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A flashing yellow arrow for a left turn means:', '["Protected turn; oncoming traffic stopped", "Turn allowed after yielding to oncoming traffic and pedestrians", "Left turn prohibited", "Stop and wait for green arrow"]'::jsonb, 1, 'You may turn left but must yield to oncoming traffic and pedestrians.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A sign with a bicycle symbol marks:', '["Bicycles prohibited", "Bicycle lane or route", "Bike shop nearby", "No pedestrians"]'::jsonb, 1, 'Bicycle symbols mark lanes or shared routes for cyclists.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A pedestrian symbol on a yellow sign warns:', '["Pedestrians prohibited", "Pedestrian crossing or area ahead", "No sidewalk", "School bus stop only"]'::jsonb, 1, 'These signs alert drivers to watch for people walking.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A winding road symbol warns that:', '["The road is closed", "The road has curves ahead", "Trucks only", "Steep grade ahead"]'::jsonb, 1, 'The winding road symbol warns of multiple curves ahead.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A flagger in a work zone means you must:', '["Ignore temporary signs", "Follow the flagger instructions", "Speed up to clear the zone", "Use the shoulder"]'::jsonb, 1, 'Flaggers control traffic and their directions must be obeyed.', 'road signs', 'easy', 'drivesight-ca-100', true),
  ('CA', 'At a four-way stop, who goes first?', '["The largest vehicle", "The driver who arrived first", "The driver on the left", "Whoever honks first"]'::jsonb, 1, 'At four-way stops, the first vehicle to stop generally proceeds first.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When two vehicles arrive at a four-way stop at the same time, who yields?', '["The driver on the right goes first", "The driver on the left goes first", "The faster vehicle", "The truck always goes"]'::jsonb, 0, 'When arriving together, yield to the driver on your right.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'At an uncontrolled intersection, you should:', '["Assume you have the right of way", "Slow down and be ready to yield if needed", "Honk and proceed", "Stop only if a sign is present"]'::jsonb, 1, 'Slow down and yield to avoid collisions when no signs or signals control the intersection.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When entering a roundabout, you must yield to:', '["Traffic exiting the roundabout", "Traffic already in the roundabout", "Pedestrians only after you enter", "No one"]'::jsonb, 1, 'Entering traffic must yield to vehicles already circulating.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'A pedestrian in a marked crosswalk has:', '["No special right of way", "The right of way", "Right of way only at night", "Right of way only with a green light"]'::jsonb, 1, 'Drivers must yield to pedestrians in crosswalks.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When turning left at a green light without an arrow, you must:', '["Turn immediately", "Yield to oncoming traffic and pedestrians", "Wait for a green arrow only", "Honk and turn"]'::jsonb, 1, 'Left turns on solid green require yielding to oncoming traffic and pedestrians.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'At a T-intersection without signs, who must yield?', '["The driver on the continuing road", "The driver on the road that ends", "The slower vehicle", "Neither driver"]'::jsonb, 1, 'The driver on the road that ends must yield to through traffic.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When a funeral procession is led by an escort with flashing lights, you should:', '["Cut into the procession", "Yield and not interrupt the procession", "Pass on the right shoulder", "Honk to warn them"]'::jsonb, 1, 'Do not break into or interrupt a funeral procession.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When merging onto a freeway, who has the right of way?', '["The merging driver", "Traffic already on the freeway", "The slower vehicle", "Trucks only"]'::jsonb, 1, 'Drivers on the freeway have the right of way; merge when safe.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When a school bus has red lights flashing on a two-lane road, you must:', '["Pass slowly", "Stop until the lights stop flashing", "Pass if no children visible", "Honk and proceed"]'::jsonb, 1, 'You must stop for flashing red school bus lights on undivided roads.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When emergency vehicles approach with sirens and lights, you should:', '["Speed up", "Pull to the right edge and stop if safe", "Stop in the intersection", "Follow closely behind"]'::jsonb, 1, 'Pull right and stop to clear a path for emergency vehicles.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'At a yield sign, you must:', '["Stop always for three seconds", "Slow or stop as needed and give right of way", "Maintain speed", "Turn without looking"]'::jsonb, 1, 'Yield means give right of way; stop if needed.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If traffic signals are blacked out and not working, treat the intersection as:', '["Green light for main road", "A four-way stop", "Free-for-all", "Yield only for left turns"]'::jsonb, 1, 'A dark signal should be treated as an all-way stop.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When exiting a driveway onto a street, you must yield to:', '["Only pedestrians", "Pedestrians and vehicles on the roadway", "No one if you signal", "Vehicles behind you only"]'::jsonb, 1, 'Entering traffic must yield to pedestrians and road users.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If you reach an intersection with a non-functioning signal at the same time as another car, you should:', '["Proceed quickly", "Treat it as a four-way stop and take turns safely", "Honk to claim right of way", "Turn left first always"]'::jsonb, 1, 'Use caution and follow four-way stop rules when signals fail.', 'right of way', 'medium', 'drivesight-ca-100', true),
  ('CA', 'A steady red light means:', '["Slow down", "Stop and remain stopped until the light turns green", "Proceed with caution", "Yield only to the right"]'::jsonb, 1, 'Stop at the limit line or crosswalk and wait for green.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A steady yellow light means:', '["Speed up", "The light is about to turn red; stop if you can do so safely", "Go immediately", "Stop only at night"]'::jsonb, 1, 'Yellow warns the signal is changing; stop safely if possible.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A flashing red light means:', '["Proceed without stopping", "Stop, then go when safe", "Yield only", "Green light coming"]'::jsonb, 1, 'Treat a flashing red like a stop sign.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A flashing yellow light means:', '["Stop", "Slow down and proceed with caution", "Road closed", "No right turn"]'::jsonb, 1, 'Flashing yellow warns drivers to proceed carefully.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A green arrow pointing left allows you to:', '["Turn left with a protected movement if no sign prohibits", "Turn left without yielding", "Go straight only", "Park in the intersection"]'::jsonb, 0, 'A green arrow gives a protected turn in that direction.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A red arrow pointing left means:', '["Turn left after yielding", "Do not turn left until the arrow changes", "Stop only if pedestrians present", "Merge left"]'::jsonb, 1, 'You may not turn in the direction of a red arrow.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'If the light turns yellow as you approach, you should:', '["Accelerate to beat the red", "Stop if you can do so safely", "Ignore it", "Honk"]'::jsonb, 1, 'Do not speed up for yellow; stop safely when possible.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'At a red light, a right turn is allowed when:', '["Never", "After stopping and yielding unless a sign prohibits it", "Without stopping if clear", "Only with a green arrow"]'::jsonb, 1, 'Right on red is allowed after a full stop and yielding unless posted otherwise.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Pedestrian countdown numbers show:', '["Speed limit", "Seconds left to cross for pedestrians", "Parking time limit", "Bus schedule"]'::jsonb, 1, 'Countdowns tell pedestrians how much crossing time remains.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'If a traffic signal is green but traffic is blocking the intersection, you should:', '["Enter and wait in the intersection", "Wait until you can clear the intersection completely", "Honk", "Use the shoulder"]'::jsonb, 1, 'Do not block the box; wait until you can clear the intersection.', 'traffic signals', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Before changing lanes, you should:', '["Signal and check mirrors and blind spots", "Signal only on freeways", "Change quickly without signaling", "Honk continuously"]'::jsonb, 0, 'Signal early and check mirrors and blind spots before moving.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When turning right, you should usually turn from:', '["The lane closest to the right curb", "Any open lane", "The center lane", "The shoulder"]'::jsonb, 0, 'Right turns are normally made from the rightmost lane.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When turning left from a two-way street onto a two-way street, start from:', '["The far right lane", "The lane closest to the center line or marked left-turn lane", "The shoulder", "Any lane"]'::jsonb, 1, 'Begin left turns from the lane nearest the center or a marked turn lane.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'A U-turn in a business district is:', '["Always legal", "Legal only at intersections or openings unless prohibited", "Always illegal", "Legal anywhere at night"]'::jsonb, 1, 'In business districts, U-turns are limited to intersections or openings unless posted.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'You must signal at least how long before a turn in California?', '["50 feet", "100 feet", "200 feet", "500 feet"]'::jsonb, 1, 'California law requires signaling at least 100 feet before turning.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When passing a bicyclist, California law generally requires:', '["Honk continuously", "At least three feet of space when passing", "Pass in the same lane at any speed", "Flash high beams"]'::jsonb, 1, 'Give at least three feet of clearance when passing a bicyclist.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If your lane ends and you must merge, you should:', '["Stop in the lane", "Match speed, signal, and merge when safe", "Force other drivers to slow", "Use the median"]'::jsonb, 1, 'Adjust speed and merge smoothly when a lane ends.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When making a legal U-turn, you must yield to:', '["No one", "All approaching traffic and pedestrians", "Only trucks", "Only vehicles behind you"]'::jsonb, 1, 'Yield to all traffic and pedestrians before completing a U-turn.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Hand signals are required if:', '["You are on a freeway", "Your turn signals are not working", "It is raining", "You are parking"]'::jsonb, 1, 'Use hand signals if electronic signals fail.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When turning across a bike lane before a right turn, you should:', '["Merge into the bike lane when safe before turning", "Turn across without looking", "Stop in the travel lane", "Honk at cyclists"]'::jsonb, 0, 'Enter the bike lane within 200 feet of the turn when safe.', 'lane changes and turning', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When parking downhill with a curb, turn your front wheels:', '["Toward the curb", "Away from the curb", "Straight ahead", "Toward the street"]'::jsonb, 0, 'Turn wheels toward the curb so the vehicle rolls into the curb if it moves.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When parking uphill with a curb, turn your front wheels:', '["Toward the curb", "Away from the curb (toward the street)", "Straight", "Left only"]'::jsonb, 1, 'Turn wheels away from the curb so the vehicle rolls into the curb if it rolls back.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'A blue curb means:', '["Loading zone", "Parking for disabled persons with a valid placard", "No parking", "Taxi only"]'::jsonb, 1, 'Blue curbs are for disabled parking with proper placards or plates.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'A green curb means:', '["No stopping", "Limited-time parking as posted", "Bus zone", "Fire lane"]'::jsonb, 1, 'Green curbs allow short-term parking for the posted time.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'You may not park within how many feet of a fire hydrant?', '["5 feet", "10 feet", "15 feet", "20 feet"]'::jsonb, 2, 'Do not park within 15 feet of a fire hydrant.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'You may not park within how many feet of a crosswalk at an intersection?', '["10 feet", "15 feet", "20 feet", "25 feet"]'::jsonb, 2, 'Stay far enough from crosswalks so pedestrians remain visible.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Double parking means:', '["Parking between two spaces", "Parking on the roadway beside a parked vehicle", "Parking in a garage", "Parking at a meter"]'::jsonb, 1, 'Double parking blocks traffic and is illegal.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When parallel parking, your wheels should be within how many inches of the curb?', '["6 inches", "18 inches", "36 inches", "Any distance"]'::jsonb, 1, 'Wheels should generally be within 18 inches of the curb.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'You must not leave a child under what age alone in a vehicle if unsafe?', '["6 years", "8 years", "10 years", "12 years"]'::jsonb, 1, 'Leaving young children unattended in vehicles can be dangerous and illegal.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Parking in a space marked for disabled persons without a placard is:', '["Allowed at night", "Illegal", "Allowed for five minutes", "Allowed with hazards on"]'::jsonb, 1, 'Disabled spaces require proper placards or plates.', 'parking', 'medium', 'drivesight-ca-100', true),
  ('CA', 'California default speed limit in a residential or business district unless posted is:', '["15 mph", "25 mph", "35 mph", "45 mph"]'::jsonb, 1, 'The default limit is 25 mph unless otherwise posted.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Unless posted otherwise, the speed limit in a school zone when children are present is:', '["15 mph", "25 mph", "35 mph", "45 mph"]'::jsonb, 1, 'School zones are commonly 25 mph when children are present.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'On most California freeways, the maximum speed limit unless posted is:', '["55 mph", "65 mph", "75 mph", "85 mph"]'::jsonb, 1, 'Many freeways have a 65 mph limit unless posted otherwise.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'When driving in fog, you should:', '["Use high beams", "Slow down and use low-beam headlights", "Drive the posted limit", "Follow closely"]'::jsonb, 1, 'Low beams reduce glare; slow down in fog.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'The Basic Speed Law means you must never drive faster than is:', '["Posted on the sign only", "Reasonable for current conditions", "What other drivers are doing", "50 mph"]'::jsonb, 1, 'You must drive at a speed reasonable for conditions even if under the posted limit.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'When towing a trailer, you should usually:', '["Drive faster to reduce delay", "Drive slower and allow more following distance", "Use high beams always", "Pass frequently"]'::jsonb, 1, 'Heavier loads need slower speeds and more space.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Speed limits in highway construction zones when workers are present:', '["Never change", "May be reduced and must be obeyed", "Are suggestions only", "Apply only to trucks"]'::jsonb, 1, 'Reduced limits in work zones protect workers and must be followed.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'If you are driving 65 mph in rain on a crowded freeway, you are likely:', '["Following the Basic Speed Law", "Driving too fast for conditions", "Driving too slow", "Exempt from limits"]'::jsonb, 1, 'Rain reduces traction; slower speeds are often required.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'When approaching a blind curve, you should:', '["Maintain speed in your lane", "Slow down and keep right", "Cross the center line", "Stop in the lane"]'::jsonb, 1, 'Slow down and stay right to avoid oncoming traffic you cannot see.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Driving well below the speed limit in normal traffic can be:', '["Always safest", "Dangerous and impede traffic flow", "Required", "Illegal only on freeways"]'::jsonb, 1, 'Driving too slowly can block traffic and increase risk.', 'speed limits', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Near a school when children are outside, you should:', '["Maintain normal speed", "Slow down and watch for children", "Honk often", "Use high beams"]'::jsonb, 1, 'Expect unpredictable child movements near schools.', 'school zones', 'easy', 'drivesight-ca-100', true),
  ('CA', 'A crossing guard showing a stop sign means you must:', '["Slow down", "Stop and remain stopped until directed to proceed", "Go around quickly", "Only stop if children are in your lane"]'::jsonb, 1, 'Obey crossing guards like traffic control officers.', 'school zones', 'easy', 'drivesight-ca-100', true),
  ('CA', 'School zone signs often use which color for visibility?', '["Orange", "Fluorescent yellow-green", "Blue", "Brown"]'::jsonb, 1, 'Fluorescent yellow-green improves visibility for school warnings.', 'school zones', 'easy', 'drivesight-ca-100', true),
  ('CA', 'When a school bus stops on your side of an undivided road with flashing red lights, you:', '["May pass at 10 mph", "Must stop until the lights stop flashing", "May pass if no kids visible", "Must honk"]'::jsonb, 1, 'On your side of the road, stop for the bus red lights.', 'school zones', 'easy', 'drivesight-ca-100', true),
  ('CA', 'Children are most at risk when:', '["On sidewalks only", "Entering or leaving school buses and crossing streets", "Inside classrooms", "On freeways"]'::jsonb, 1, 'Loading and unloading zones require extra driver caution.', 'school zones', 'easy', 'drivesight-ca-100', true),
  ('CA', 'When you see a stationary emergency vehicle with flashing lights on a freeway, you should:', '["Maintain speed", "Move over a lane away if safe, or slow down", "Stop immediately in your lane", "Take photos"]'::jsonb, 1, 'Move over or slow down for stopped emergency vehicles (Move Over law).', 'emergency vehicles', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If an emergency vehicle approaches from behind with lights and siren, you should:', '["Stop in the intersection", "Pull to the right and stop when safe", "Speed up", "Turn left quickly"]'::jsonb, 1, 'Pull right and stop to let emergency vehicles pass.', 'emergency vehicles', 'medium', 'drivesight-ca-100', true),
  ('CA', 'It is illegal to follow an emergency vehicle responding to a call within:', '["100 feet", "300 feet", "500 feet", "1000 feet"]'::jsonb, 2, 'Do not follow within 500 feet of responding emergency vehicles.', 'emergency vehicles', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If you are in an intersection when an emergency vehicle approaches, you should:', '["Stop in the intersection", "Clear the intersection, then pull over", "Back up", "Turn off your lights"]'::jsonb, 1, 'Clear the intersection first, then pull over safely.', 'emergency vehicles', 'medium', 'drivesight-ca-100', true),
  ('CA', 'You must not drive over fire hoses unless:', '["You are late", "Authorized by a fire official", "Traffic is heavy", "You have four-wheel drive"]'::jsonb, 1, 'Only cross fire hoses when authorized by fire personnel.', 'emergency vehicles', 'medium', 'drivesight-ca-100', true),
  ('CA', 'For drivers under 21 in California, any measurable alcohol in the blood is:', '["Allowed up to 0.05%", "Illegal (zero tolerance)", "Allowed with parental consent", "Allowed on highways only"]'::jsonb, 1, 'Drivers under 21 may not drive with any measurable alcohol.', 'alcohol/DUI', 'hard', 'drivesight-ca-100', true),
  ('CA', 'The legal BAC limit for drivers 21 and older is generally:', '["0.02%", "0.08%", "0.10%", "0.15%"]'::jsonb, 1, '0.08% BAC is the general legal limit for adults 21 and over.', 'alcohol/DUI', 'hard', 'drivesight-ca-100', true),
  ('CA', 'Implied consent means if you are arrested for DUI you must:', '["Pay a fine on the spot", "Submit to a chemical test of your blood or breath", "Surrender your vehicle permanently", "Take a road test"]'::jsonb, 1, 'Licensed drivers agree to chemical testing when lawfully arrested for DUI.', 'alcohol/DUI', 'hard', 'drivesight-ca-100', true),
  ('CA', 'A DUI conviction can result in:', '["License suspension and fines", "Only a warning", "No insurance change", "Automatic expungement"]'::jsonb, 0, 'DUI can lead to suspension, fines, and other penalties.', 'alcohol/DUI', 'hard', 'drivesight-ca-100', true),
  ('CA', 'The best way to avoid DUI is to:', '["Drink coffee after alcohol", "Plan a sober ride before drinking", "Drive slowly", "Open windows while driving"]'::jsonb, 1, 'Plan ahead with a sober driver or ride service.', 'alcohol/DUI', 'hard', 'drivesight-ca-100', true),
  ('CA', 'The three-second rule helps you maintain:', '["Speed", "A safe following distance", "Lane position", "Fuel economy"]'::jsonb, 1, 'Pick a fixed point; when the car ahead passes it, you should reach it in at least three seconds.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If another driver is tailgating you, you should:', '["Brake suddenly", "Increase following distance ahead and change lanes when safe", "Speed up sharply", "Block them"]'::jsonb, 1, 'Increase space ahead so you can brake gradually if needed.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'When you feel drowsy while driving, you should:', '["Open windows and keep driving", "Pull off in a safe place and rest", "Drink only soda", "Speed up to arrive faster"]'::jsonb, 1, 'Rest is the safest response to drowsy driving.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Hydroplaning is best handled by:', '["Braking hard", "Easing off the gas and steering straight until traction returns", "Accelerating", "Turning sharply"]'::jsonb, 1, 'Ease off the accelerator and steer straight until you regain control.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If your vehicle starts to skid, you should:', '["Steer in the direction you want to go and avoid sudden braking", "Brake hard immediately", "Accelerate", "Close your eyes briefly"]'::jsonb, 0, 'Steer smoothly toward your intended path and avoid abrupt inputs.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Scanning the road 10 to 15 seconds ahead helps you:', '["Use your phone safely", "See hazards early", "Speed in traffic", "Ignore mirrors"]'::jsonb, 1, 'Looking far ahead gives time to react to hazards.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Large trucks have bigger blind spots called:', '["Safety zones", "No-zones", "Free zones", "Pass zones"]'::jsonb, 1, 'Stay out of truck no-zones where the driver cannot see you.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'At night, you should dim high beams within how many feet of an oncoming vehicle?', '["200 feet", "500 feet", "1000 feet", "1500 feet"]'::jsonb, 1, 'Dim high beams within 500 feet of oncoming traffic.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'If your right wheels drop off the pavement, you should:', '["Jerk the wheel back quickly", "Grip the wheel, ease off the gas, and return when safe", "Brake hard", "Accelerate back"]'::jsonb, 1, 'Ease off the gas and re-enter gradually when safe.', 'defensive driving', 'medium', 'drivesight-ca-100', true),
  ('CA', 'Defensive driving means:', '["Assuming other drivers will always yield", "Anticipating hazards and driving to prevent collisions", "Driving the speed limit always", "Using hazard lights often"]'::jsonb, 1, 'Defensive driving focuses on preventing crashes before they happen.', 'defensive driving', 'medium', 'drivesight-ca-100', true);
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('CA', 'In California, municipal curbs are often painted specific colors to indicate parking rules. What does a painted green curb signify?', '["Parking is strictly reserved for zero-emission or electric vehicles", "Parking is permitted for a limited time, which is usually painted on the curb or posted on a sign", "The zone is reserved exclusively for loading and unloading passengers", "No stopping, standing, or parking under any circumstances"]'::jsonb, 1, 'A green painted curb in California means parking is limited to a specific amount of time. The time limit is typically painted directly on the curb or posted on a nearby sign.', 'parking', 'medium', 'drivesight-ca-extra-12', true),
  ('CA', 'California is unique regarding its traffic laws for motorcycles. What is the legal status of ''lane splitting'' (riding a motorcycle between rows of stopped or moving traffic) in the state?', '["It is strictly illegal and carries heavy moving violation fines", "It is legal only when freeway traffic is completely stopped", "It is fully legal if done in a safe and prudent manner", "It is only permitted for active duty law enforcement officers"]'::jsonb, 2, 'California is the first state to formally legalize lane splitting. Motorcyclists are legally allowed to ride between lanes of traffic as long as it is done safely and prudently.', 'motorcycle_awareness', 'medium', 'drivesight-ca-extra-12', true),
  ('CA', 'Unless signage explicitly posts a different speed, what is the maximum speed limit in a California school zone when children are present outside or crossing the street?', '["15 mph", "20 mph", "25 mph", "35 mph"]'::jsonb, 2, 'The speed limit is 25 mph when driving within 500 to 1,000 feet of a school while children are outside or crossing the street, unless posted otherwise.', 'school_zones', 'easy', 'drivesight-ca-extra-12', true),
  ('CA', 'Under California''s Zero Tolerance Law for drivers under the age of 21, what minimum Blood Alcohol Concentration (BAC) will trigger an immediate one-year license suspension?', '["0.01% or higher", "0.04% or higher", "0.05% or higher", "0.08% or higher"]'::jsonb, 0, 'California enforces a strict Zero Tolerance law for underage drinking. If a driver under 21 tests with a BAC of 0.01% or higher, their driving privilege is suspended for one year.', 'dui_alcohol_laws', 'hard', 'drivesight-ca-extra-12', true),
  ('CA', 'You arrive at a ''T'' intersection where your dead-end road meets a through highway. There are no stop or yield signs present. Who holds the right-of-way?', '["The vehicle that arrives at the intersection first", "The vehicle traveling on the dead-end road", "Vehicles traveling on the continuing through road", "The vehicle attempting to make a right turn"]'::jsonb, 2, 'At a T-intersection without STOP or YIELD signs, traffic traveling on the through road holds the right-of-way. The driver on the road that ends must yield.', 'right_of_way', 'medium', 'drivesight-ca-extra-12', true),
  ('CA', 'While traveling on a California freeway, you decide to enter the Carpool (HOV) lane, which is currently separated from your lane by a continuous solid double white line. Your legal action is to:', '["Cross the double white line carefully if your blinker has been on for 3 seconds", "Wait until the solid double white line transitions into a broken white line", "Cross only if you have three or more passengers in the vehicle", "Merge immediately if freeway traffic has slowed below 45 mph"]'::jsonb, 1, 'It is illegal to cross solid double white lines on a California freeway. You must wait for a designated entry/exit point marked by broken white lines to enter or exit the HOV lane.', 'freeway_driving', 'easy', 'drivesight-ca-extra-12', true),
  ('CA', 'When driving through dense Tule fog in the Central Valley, which vehicle lighting configuration should you use to maximize your visibility and avoid blinding yourself?', '["High-beam headlights", "Parking lights only", "Low-beam headlights", "Hazard lights with headlights turned off"]'::jsonb, 2, 'In dense fog, you should always use low-beam headlights. High beams will reflect off the moisture particles in the fog, creating glare and severely reducing your ability to see.', 'weather_driving', 'easy', 'drivesight-ca-extra-12', true),
  ('CA', 'Unless otherwise posted, what is the maximum statutory speed limit on a two-lane undivided highway in California?', '["55 mph", "60 mph", "65 mph", "70 mph"]'::jsonb, 0, 'The maximum speed limit on most California highways is 65 mph, but for a two-lane undivided highway, the maximum speed limit drops to 55 mph unless posted otherwise.', 'speed_limits', 'hard', 'drivesight-ca-extra-12', true),
  ('CA', 'A school bus is traveling ahead of you in your lane. Suddenly, its yellow lights begin flashing. What does this specific signal indicate?', '["The bus is currently boarding children and you must stop immediately", "The bus is experiencing mechanical failure and is pulling over", "The bus is preparing to stop to load or unload children; you should slow down and prepare to stop", "The bus is accelerating to merge onto a faster roadway"]'::jsonb, 2, 'Flashing yellow lights on a school bus warn drivers that the bus is preparing to stop to load or unload passengers. You should slow down and prepare to stop when the red lights flash.', 'school_zones', 'medium', 'drivesight-ca-extra-12', true),
  ('CA', 'In California, under what specific circumstance is it legally permissible to pass a vehicle on the right using the unpaved shoulder of the road?', '["When the vehicle ahead is making a left turn", "Never; passing on an unpaved shoulder is strictly prohibited", "When traffic is fully stopped and you need to reach an exit ramp", "If you are driving a four-wheel-drive vehicle"]'::jsonb, 1, 'You may never drive off the paved or main-traveled portion of the road or onto the shoulder to pass another vehicle, regardless of what the vehicle ahead is doing.', 'passing_rules', 'easy', 'drivesight-ca-extra-12', true),
  ('CA', 'Under California''s distracted driving laws, how may a driver aged 18 or older legally interact with a smartphone while operating a vehicle?', '["They may hold the phone to text if stopped at a red light", "They may hold the phone for phone calls, but not for texting", "They may only use it in hands-free mode, and it must be securely mounted to the windshield or dashboard", "They are strictly prohibited from using a smartphone in any capacity"]'::jsonb, 2, 'California drivers 18 and older may only use a smartphone if it is utilized in a completely hands-free manner (like Bluetooth or voice command) and is securely mounted out of airbag deployment zones.', 'distracted_driving', 'medium', 'drivesight-ca-extra-12', true),
  ('CA', 'You are stopped at a solid red traffic light and intend to make a right turn. Assuming no signs prohibit the maneuver, what is the proper legal sequence of actions?', '["Slow down to 5 mph, yield to cross traffic, and turn", "Come to a complete stop, yield to pedestrians and oncoming traffic, and turn only when safe", "Turn immediately, as turning right on red grants you the right-of-way", "Wait until the crosswalk countdown timer reaches zero, then turn"]'::jsonb, 1, 'To legally turn right on a solid red light in California, you must first come to a complete stop behind the limit line, yield to all pedestrians and cross traffic, and then proceed if safe.', 'traffic_signals', 'easy', 'drivesight-ca-extra-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('CO', 'To control your vehicle''s speed and prevent severe brake fade while descending a steep mountain grade in Colorado, your safest mechanical action is to:', '["Pump the brake pedal vigorously all the way down the mountain", "Shift your transmission into a lower gear", "Turn the engine off and coast in neutral", "Apply the emergency parking brake lightly"]'::jsonb, 1, 'Riding your brakes down a steep grade can cause them to overheat and fail. Shifting to a lower gear allows the engine''s compression to safely control your descent speed.', 'weather_driving', 'medium', 'drivesight-co-12', true),
  ('CO', 'In Colorado, law enforcement can charge a driver with Driving While Ability Impaired (DWAI), a lesser but serious alcohol offense, with a Blood Alcohol Concentration (BAC) as low as:', '["0.02%", "0.04%", "0.05%", "0.08%"]'::jsonb, 2, 'While standard DUI is 0.08%, Colorado law includes a DWAI charge. If your BAC is between 0.05% and 0.079%, you can be arrested for Driving While Ability Impaired.', 'dui_alcohol_laws', 'hard', 'drivesight-co-12', true),
  ('CO', 'Under Colorado''s Move Over Law, if you approach a stationary emergency vehicle or tow truck with flashing lights and traffic prevents you from safely changing lanes, you must:', '["Stop completely in your lane and wait for directions", "Maintain your speed but honk to alert the workers of your presence", "Reduce your speed to at least 20 mph below the posted speed limit", "Accelerate to clear the dangerous area quickly"]'::jsonb, 2, 'If you cannot safely shift one lane away from a stationary emergency or maintenance vehicle in Colorado, the law requires you to reduce your speed to at least 20 mph below the posted limit.', 'emergency_vehicles', 'medium', 'drivesight-co-12', true),
  ('CO', 'During severe winter snowstorms, the Colorado Department of Transportation may implement a Passenger Vehicle Traction Law (Code 15). What does this mandate for motorists?', '["All vehicles are banned from the highway except snowplows", "Vehicles must have snow tires, M+S rated tires, or carry traction devices like chains or AutoSocks", "Only four-wheel-drive (4WD) vehicles are permitted on mountain passes", "All passenger vehicles must follow behind a state pilot car"]'::jsonb, 1, 'Under a Code 15 Traction Law, all motorists must have either 4WD/AWD, snow tires, tires with the mud/snow (M+S) designation, or carry alternative traction devices like chains or AutoSocks.', 'weather_driving', 'hard', 'drivesight-co-12', true),
  ('CO', 'When approaching a multi-lane roundabout intersection in Colorado, which vehicles hold the legal right-of-way?', '["The larger, heavier commercial vehicles", "Traffic attempting to enter the roundabout from the right", "Traffic that is already circulating inside the roundabout", "Vehicles attempting to exit the roundabout"]'::jsonb, 2, 'Drivers entering a roundabout must always yield the right-of-way to vehicles, bicyclists, and pedestrians already circulating inside the traffic circle.', 'intersections', 'easy', 'drivesight-co-12', true),
  ('CO', 'When a school bus stops and activates its flashing red lights and stop arm on a standard two-lane Colorado road, drivers approaching from both directions must stop at least:', '["10 feet away", "20 feet away", "50 feet away", "100 feet away"]'::jsonb, 1, 'Colorado law requires that vehicles approaching from any direction must stop at least 20 feet away from a school bus displaying flashing red lights and an extended stop signal arm.', 'school_zones', 'medium', 'drivesight-co-12', true),
  ('CO', 'According to Colorado state law, what are the restrictions regarding cell phone use for drivers who are under the age of 18?', '["They may use a cell phone only if it is completely hands-free", "They may send text messages while stopped at a red traffic light", "They are strictly prohibited from using a cell phone for any reason, except to contact emergency services", "They may use a handheld phone if a parent is in the passenger seat"]'::jsonb, 2, 'Drivers under 18 in Colorado are prohibited from using a mobile phone while driving for any reason, including hands-free devices, unless they are contacting the police or fire department in an emergency.', 'distracted_driving', 'easy', 'drivesight-co-12', true),
  ('CO', 'Unless otherwise posted by signage, what is the maximum statutory speed limit on narrow, winding mountain highways and blind curves in Colorado?', '["15 mph", "20 mph", "25 mph", "35 mph"]'::jsonb, 1, 'Due to the treacherous nature of the terrain, Colorado sets the baseline maximum speed limit on narrow, winding mountain highways and blind curves at 20 mph.', 'speed_limits', 'hard', 'drivesight-co-12', true),
  ('CO', 'You are driving on a multi-lane Colorado highway and a motorcyclist is traveling in your lane ahead of you. Are you legally permitted to share the same lane side-by-side with the motorcycle?', '["Yes, if the lane is wide enough to accommodate both comfortably", "Yes, but only during daylight hours", "No, a passenger vehicle may never share a lane with a motorcycle", "No, unless the motorcyclist motions for you to pull up next to them"]'::jsonb, 2, 'Motorcycles are entitled to the full width of a traffic lane. While two motorcycles may share a single lane side-by-side, a passenger car is strictly prohibited from sharing a lane with a motorcycle.', 'motorcycle_awareness', 'medium', 'drivesight-co-12', true),
  ('CO', 'You are parallel parking your vehicle facing downhill on a steep mountain street that does not have a physical curb. To secure the vehicle safely, which way should you turn your front wheels?', '["Perfectly straight ahead", "Sharply to the left (toward the center of the road)", "Sharply to the right (toward the shoulder or edge of the road)", "It does not matter as long as the emergency brake is fully engaged"]'::jsonb, 2, 'When parking downhill without a curb, always turn your wheels sharply to the right. If the brakes fail, the vehicle will roll off the roadway into the shoulder/dirt rather than into oncoming traffic.', 'parking', 'easy', 'drivesight-co-12', true),
  ('CO', 'When passing a bicyclist who is traveling in the same direction on a Colorado roadway, state law mandates that a motor vehicle must leave a minimum physical clearance of at least:', '["2 feet", "3 feet", "5 feet", "One full traffic lane"]'::jsonb, 1, 'Colorado law requires motorists to give bicyclists at least 3 feet of space between the widest part of their vehicle and the widest part of the bicyclist when passing.', 'passing_rules', 'medium', 'drivesight-co-12', true),
  ('CO', 'As you travel down an entrance ramp to merge onto I-25 in Colorado, your primary responsibility as the merging driver is to:', '["Force highway traffic to change lanes by signaling aggressively", "Drive to the very end of the ramp and come to a complete stop to check for traffic", "Accelerate to match the speed of freeway traffic and yield to vehicles already on the highway", "Cross the solid white line early to merge as quickly as possible"]'::jsonb, 2, 'The vehicle entering the freeway must yield the right-of-way. You should use the acceleration lane to match the speed of highway traffic and merge seamlessly when a safe gap appears.', 'merging', 'easy', 'drivesight-co-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('CT', 'Under Connecticut law, what are the restrictions regarding mobile phone use for drivers who are 16 or 17 years old?', '["They may use a hands-free device as long as the phone remains mounted", "They are completely prohibited from using any mobile electronic device, even if it is hands-free", "They may send text messages only when completely stopped at a traffic light", "They may use a handheld phone only to check GPS directions"]'::jsonb, 1, 'Connecticut has strict distracted driving laws for minors. Drivers under the age of 18 are prohibited from using any mobile electronic device, whether handheld or hands-free, except in the case of a genuine emergency.', 'distracted_driving', 'medium', 'drivesight-ct-12', true),
  ('CT', 'Connecticut enforces a Zero-Tolerance law for underage drinking and driving. A 16- or 17-year-old driver will face an administrative license suspension if they drive with an elevated Blood Alcohol Content (BAC) of at least:', '["0.01%", "0.02%", "0.05%", "0.08%"]'::jsonb, 1, 'Under Connecticut''s Zero-Tolerance law, a 16- or 17-year-old driver will have their license suspended for at least one year if they are found driving with a BAC equal to or greater than 0.02%.', 'dui_alcohol_laws', 'hard', 'drivesight-ct-12', true),
  ('CT', 'In Connecticut, state law requires you to turn on your vehicle''s headlights whenever:', '["You are driving on an interstate highway", "Your vehicle''s windshield wipers are in continuous use due to weather conditions", "The temperature drops below freezing", "You enter any marked construction zone"]'::jsonb, 1, 'Connecticut law requires drivers to activate their headlights whenever their windshield wipers are in continuous use to clear rain, snow, or other precipitation, ensuring better visibility for everyone on the road.', 'weather_driving', 'easy', 'drivesight-ct-12', true),
  ('CT', 'When approaching a stationary emergency vehicle or tow truck displaying flashing lights on a multi-lane Connecticut highway, the state''s ''Move Over'' law requires you to:', '["Maintain your speed but honk your horn to alert them of your presence", "Reduce your speed significantly and move over one lane away from the stationary vehicle, if safe to do so", "Stop completely in your lane and wait for an officer to wave you around", "Accelerate to pass the hazard as quickly as possible"]'::jsonb, 1, 'The Move Over law protects roadside workers and emergency responders. If you cannot safely move over a lane, you must slow down to a reasonable and safe speed below the posted limit.', 'emergency_vehicles', 'medium', 'drivesight-ct-12', true),
  ('CT', 'You are parking your vehicle facing uphill on a street that has a raised physical curb. To ensure the vehicle doesn''t roll into traffic if the brakes fail, your front wheels should be:', '["Kept perfectly straight", "Turned sharply toward the curb", "Turned sharply away from the curb", "Resting directly on top of the curb"]'::jsonb, 2, 'When parked facing uphill next to a curb, turning the steering wheel away from the curb ensures that if the vehicle begins to roll backward, the back of the front tire will hit the curb and stop the vehicle.', 'parking', 'medium', 'drivesight-ct-12', true),
  ('CT', 'A school bus is stopped ahead of you on an undivided two-lane road in Connecticut, and its red lights are actively flashing. What is your legal obligation?', '["You must come to a complete stop at least 10 feet away and remain stopped until the red lights turn off", "You may proceed at 15 mph if no children are actively in the crosswalk", "Only traffic traveling in the same direction as the bus is required to stop", "You must honk your horn to warn children before passing the bus carefully"]'::jsonb, 0, 'In Connecticut, drivers approaching a stopped school bus with flashing red lights from either direction on an undivided highway must stop at least 10 feet away to allow children to cross safely.', 'school_zones', 'easy', 'drivesight-ct-12', true),
  ('CT', 'When passing a bicyclist traveling in the same direction on a Connecticut roadway, a motorist must leave a minimum safe passing distance of at least:', '["1 foot", "2 feet", "3 feet", "5 feet"]'::jsonb, 2, 'Connecticut''s safe passing law mandates that drivers must provide at least 3 feet of physical clearance when passing a bicyclist on the road.', 'passing_rules', 'medium', 'drivesight-ct-12', true),
  ('CT', 'You arrive at an uncontrolled intersection at the exact same time as another passenger vehicle located on your right. Who holds the legal right-of-way?', '["You, because you are on the left", "The vehicle on the right", "Whichever vehicle is larger", "The vehicle traveling at a faster speed"]'::jsonb, 1, 'At an uncontrolled intersection, the fundamental right-of-way rule dictates that the vehicle on the left must yield to the vehicle on the right when both arrive at the same time.', 'right_of_way', 'easy', 'drivesight-ct-12', true),
  ('CT', 'To maintain a safe following distance under normal driving conditions, Connecticut recommends that drivers utilize the:', '["One car length rule for every 10 mph of speed", "Two-second rule", "Three-second rule", "Five-second rule"]'::jsonb, 2, 'The three-second rule is the recommended safe following distance in Connecticut under ideal conditions. This should be increased during inclement weather or when following large trucks or motorcycles.', 'defensive_driving', 'easy', 'drivesight-ct-12', true),
  ('CT', 'When you approach a crosswalk and notice a pedestrian carrying a white cane or accompanied by a guide dog, you must:', '["Tap your horn gently to alert them to your presence", "Slow down and proceed around them cautiously", "Yield the right-of-way and come to a complete stop", "Roll down your window and give verbal directions"]'::jsonb, 2, 'Drivers must always yield the right-of-way and come to a complete stop for pedestrians who are blind or visually impaired, identified by a white cane or a guide dog.', 'pedestrian_safety', 'easy', 'drivesight-ct-12', true),
  ('CT', 'When utilizing an acceleration lane to enter a Connecticut highway, your primary goal should be to:', '["Drive to the end of the lane and stop completely to look for a gap", "Match the speed of highway traffic and merge smoothly when a safe gap appears", "Force highway drivers to change lanes by signaling aggressively", "Enter the highway at a cautious 30 mph"]'::jsonb, 1, 'The acceleration lane is designed to allow entering vehicles to build their speed to match the flow of highway traffic, making merging seamless and safe.', 'merging', 'medium', 'drivesight-ct-12', true),
  ('CT', 'You approach an intersection displaying a flashing red traffic signal. How should you treat this light under Connecticut law?', '["The same as a yield sign, slowing down and proceeding if clear", "The same as a stop sign, coming to a complete stop before proceeding safely", "You must stop and wait for the light to turn solid green", "Proceed with caution without stopping, as you have the right-of-way"]'::jsonb, 1, 'A flashing red traffic light carries the exact same legal meaning as a stop sign. You must come to a complete stop, yield to cross traffic and pedestrians, and proceed only when clear.', 'traffic_signals', 'easy', 'drivesight-ct-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('DE', 'Under Delaware''s distracted driving laws, what is the policy regarding the use of handheld electronic devices while driving?', '["They are prohibited only for drivers under the age of 18", "They are banned entirely for all drivers, making it illegal to hold a phone to talk, text, or browse", "They may be used to read messages, but not to type them", "They are legal to use as long as the vehicle is traveling under 40 mph"]'::jsonb, 1, 'Delaware enforces a strict hands-free law. It is illegal for all drivers, regardless of age, to use a handheld electronic device while operating a motor vehicle.', 'distracted_driving', 'easy', 'drivesight-de-12', true),
  ('DE', 'To protect highway construction crews, Delaware law authorizes what specific penalty enhancement for traffic violations committed within an active work zone?', '["The automatic suspension of the driver''s license for 30 days", "Fines for associated traffic offenses are doubled", "The violator''s vehicle is subject to immediate impoundment", "Community service is mandatory instead of monetary fines"]'::jsonb, 1, 'Under Delaware law, fines for associated traffic violations, including speeding, are doubled when the offense is committed within the limits of a highway work zone.', 'work_zones', 'medium', 'drivesight-de-12', true),
  ('DE', 'In Delaware, driving a vehicle on a public roadway at a speed of 90 miles per hour or greater will automatically result in what severe charge?', '["A simple speeding infraction with no points assessed", "A warning and mandatory defensive driving course", "Reckless driving", "A felony conviction"]'::jsonb, 2, 'According to the Delaware Code, driving a vehicle on a public roadway at 90 mph or more is explicitly classified as reckless driving, carrying significant fines and potential license suspension.', 'speed_limits', 'hard', 'drivesight-de-12', true),
  ('DE', 'When you are preparing to enter a multi-lane roundabout in Delaware, which traffic holds the legal right-of-way?', '["Vehicles attempting to enter the roundabout from your right", "Vehicles that are already circulating inside the roundabout", "Commercial trucks and large SUVs", "Vehicles attempting to exit the roundabout"]'::jsonb, 1, 'When approaching a roundabout, drivers must yield to vehicles, bicyclists, and pedestrians that are already actively circulating within the intersection.', 'intersections', 'easy', 'drivesight-de-12', true),
  ('DE', 'For a standard Delaware driver over the age of 21, it is illegal to operate a motor vehicle with a Blood Alcohol Concentration (BAC) of:', '["0.02% or higher", "0.04% or higher", "0.06% or higher", "0.08% or higher"]'::jsonb, 3, 'In Delaware, as in the rest of the nation, a BAC of 0.08% or higher constitutes driving under the influence for standard non-commercial drivers over the age of 21.', 'dui_alcohol_laws', 'easy', 'drivesight-de-12', true),
  ('DE', 'When approaching a railroad crossing in Delaware where red warning lights are flashing and gates are lowered, you must stop your vehicle:', '["Directly on the tracks to wait", "Between 15 and 50 feet from the nearest rail", "No less than 100 feet away", "Only if you physically see a train approaching"]'::jsonb, 1, 'State law mandates that when railroad crossing gates are lowered or warning signals are active, you must come to a complete stop between 15 and 50 feet from the nearest rail.', 'railroad_crossings', 'hard', 'drivesight-de-12', true),
  ('DE', 'You are driving on a two-lane road in Delaware and a school bus traveling in the opposite direction has stopped with its red lights flashing. What must you do?', '["Slow down to 10 mph and pass with extreme caution", "You are not required to stop because you are in the opposing lane", "Come to a complete stop and remain stopped until the red lights cease flashing", "Honk your horn before passing the bus on the left"]'::jsonb, 2, 'On a two-lane undivided highway, traffic traveling in both directions must come to a full stop for a school bus with actively flashing red lights.', 'school_zones', 'medium', 'drivesight-de-12', true),
  ('DE', 'Delaware''s Move Over law requires motorists to shift over a lane or slow down significantly for which of the following stationary vehicles with active flashing lights?', '["Police vehicles and ambulances only", "Fire engines only", "Any authorized emergency vehicle, tow truck, or DelDOT vehicle", "Only vehicles actively blocking a travel lane"]'::jsonb, 2, 'The Move Over law explicitly protects police, fire, ambulance, tow trucks, and Delaware Department of Transportation (DelDOT) vehicles actively displaying their warning lights.', 'emergency_vehicles', 'medium', 'drivesight-de-12', true),
  ('DE', 'Delaware law mandates that all vehicles must have their headlights turned on during which specific time period?', '["Only when visibility is less than 500 feet", "From one-half hour after sunset to one-half hour before sunrise", "From 8:00 PM to 6:00 AM exclusively", "Whenever the vehicle is traveling faster than 55 mph"]'::jsonb, 1, 'You are required to use your headlights from a half-hour after sunset until a half-hour before sunrise, or whenever visibility is poor.', 'weather_driving', 'medium', 'drivesight-de-12', true),
  ('DE', 'You are preparing to make a right turn at a solid red traffic light in Delaware. Unless a sign prohibits it, what is the correct legal procedure?', '["Slow down, verify there is no cross traffic, and turn without stopping completely", "Come to a complete stop, yield the right-of-way to pedestrians and oncoming traffic, and turn when safe", "Wait for the pedestrian walk signal to end before turning", "You may turn immediately because turning right on red grants you the right-of-way"]'::jsonb, 1, 'To make a legal right turn on red, you must first come to a full and complete stop at the stop line, yield to any cross traffic or pedestrians, and then proceed when it is safe.', 'traffic_signals', 'easy', 'drivesight-de-12', true),
  ('DE', 'Commercial semi-trucks have extensive blind spots where the driver cannot see passenger vehicles. These dangerous areas are commonly referred to as the:', '["Zero-Zones", "Blind-Boxes", "No-Zones", "Phantom-Lanes"]'::jsonb, 2, 'The ''No-Zones'' are large blind spots located around the front, sides, and rear of commercial trucks. If you cannot see the truck''s mirrors, the driver cannot see you.', 'defensive_driving', 'easy', 'drivesight-de-12', true),
  ('DE', 'A solid double yellow line running down the center of a two-way Delaware roadway indicates that:', '["The lane is reserved exclusively for High Occupancy Vehicles (HOV)", "Passing is prohibited for traffic traveling in both directions", "You may pass if the vehicle ahead is traveling below the speed limit", "Passing is permitted during daylight hours only"]'::jsonb, 1, 'A solid double yellow line means that neither lane of traffic is permitted to cross the centerline to pass another vehicle.', 'lane_changes', 'easy', 'drivesight-de-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('FL', 'Under Florida''s Move Over law, if you approach a stationary emergency vehicle, tow truck, or sanitation vehicle with flashing lights on a multi-lane highway and cannot safely shift over a lane, you are legally required to:', '["Come to a complete stop in your lane and wait for the vehicle to move", "Slow down to a speed that is 20 mph less than the posted speed limit", "Maintain your speed but sound your horn to alert workers of your presence", "Accelerate quickly to pass the hazard and clear the traffic backup"]'::jsonb, 1, 'Florida''s Move Over law requires that if you cannot safely vacate the lane closest to an emergency or service vehicle, you must slow down to 20 mph below the posted speed limit. If the speed limit is 20 mph or less, you must slow down to 5 mph.', 'emergency_vehicles', 'medium', 'drivesight-fl-11', true),
  ('FL', 'Florida law explicitly requires you to turn on your vehicle''s headlights under which of the following specific weather-related conditions?', '["Whenever the temperature drops below 40 degrees Fahrenheit", "Whenever you are driving on a rural unpaved road", "Whenever your windshield wipers are activated due to rain or other precipitation", "Only when visibility is completely reduced to zero during a hurricane"]'::jsonb, 2, 'In Florida, state law strictly mandates that your headlights must be turned on whenever your windshield wipers are in use to clear rain, fog, or other precipitation.', 'weather_driving', 'easy', 'drivesight-fl-11', true),
  ('FL', 'According to Florida''s Graduated Driver License (GDL) rules, a 16-year-old licensed driver may NOT operate a vehicle during which hours, unless accompanied by a licensed driver 21 or older or driving to/from work?', '["Between 9:00 PM and 5:00 AM", "Between 11:00 PM and 6:00 AM", "Between Midnight and 6:00 AM", "Between 10:00 PM and 4:00 AM"]'::jsonb, 1, 'To protect young drivers, Florida restricts 16-year-old drivers from operating a motor vehicle between 11:00 PM and 6:00 AM unless they are driving directly to or from work, or are accompanied by a licensed driver who is at least 21 years old.', 'defensive_driving', 'hard', 'drivesight-fl-11', true),
  ('FL', 'You are driving on a Florida highway divided by a raised, five-foot concrete barrier. A school bus traveling in the opposite direction has stopped and extended its flashing red stop arm. What is your legal obligation?', '["You must come to a complete stop and remain stopped until the lights turn off", "You must slow down to 15 mph and pass with extreme caution", "You are not required to stop because the highway is separated by a physical barrier", "You must sound your horn to warn crossing children but may maintain your speed"]'::jsonb, 2, 'If a highway is divided by a raised barrier or an unpaved median at least five feet wide, drivers traveling in the opposite direction of a stopped school bus do not have to stop.', 'school_zones', 'medium', 'drivesight-fl-11', true),
  ('FL', 'Under Florida''s Zero Tolerance law, a driver under the age of 21 will face an automatic six-month license suspension if they are caught driving with a Blood Alcohol Level (BAL) of at least:', '["0.02%", "0.04%", "0.06%", "0.08%"]'::jsonb, 0, 'Florida enforces a strict Zero Tolerance policy for underage drinking. Any driver under 21 who is stopped and has a BAL of 0.02% or higher will automatically have their driving privilege suspended for six months.', 'dui_alcohol_laws', 'medium', 'drivesight-fl-11', true),
  ('FL', 'What is the specific penalty enhancement for committing a moving speed violation within an active Florida highway construction zone where workers are visibly present?', '["The violator''s license is immediately suspended for 30 days", "The standard fine for the speeding violation is automatically doubled", "The driver must perform 40 hours of community service", "The driver''s vehicle is subject to impoundment"]'::jsonb, 1, 'To protect highway workers, Florida law requires that fines for speeding violations be doubled when the offense occurs in a posted construction or work zone and workers are present.', 'work_zones', 'easy', 'drivesight-fl-11', true),
  ('FL', 'When parking your vehicle facing downhill on a Florida street that features a physical raised curb, how should you position your vehicle''s front wheels to ensure safety?', '["Turned sharply to the left (toward the center of the road)", "Kept perfectly straight", "Turned sharply to the right (toward the curb)", "Resting completely on top of the curb"]'::jsonb, 2, 'When parking downhill with a curb, turning your wheels toward the curb ensures that if the emergency brake fails, the vehicle will roll forward into the curb and stop, preventing it from entering traffic.', 'parking', 'easy', 'drivesight-fl-11', true),
  ('FL', 'You are at a Florida intersection preparing to make a left turn. The traffic signal is a solid green circular light, but there is no green arrow. What must you do?', '["Yield the right-of-way to oncoming traffic and pedestrians, turning only when safe", "Turn immediately, as the solid green light gives you the absolute right-of-way", "Wait in the intersection until the light turns red, then quickly complete the turn", "Flash your high beams to signal oncoming traffic to stop before you turn"]'::jsonb, 0, 'A solid green light means you can proceed, but you do not have a protected turn. When turning left on a solid green, you must always yield the right-of-way to all oncoming traffic and pedestrians.', 'intersections', 'medium', 'drivesight-fl-11', true),
  ('FL', 'When passing a motorcycle traveling in the same direction on a multi-lane Florida highway, you must:', '["Share the lane with the motorcycle if there is enough physical room", "Move completely into the adjacent lane to pass, as motorcycles are entitled to the full width of their lane", "Pass the motorcycle using the right-hand shoulder if traffic is heavy", "Honk your horn continuously while passing to ensure the rider sees you"]'::jsonb, 1, 'Motorcycles have the exact same right to the full width of a traffic lane as a standard passenger vehicle. It is illegal and highly dangerous for a car to try and share a lane side-by-side with a motorcycle while passing.', 'motorcycle_awareness', 'easy', 'drivesight-fl-11', true),
  ('FL', 'In Florida, if you approach an intersection and see a pedestrian attempting to cross while carrying a white cane tipped with red, or using a guide dog, you must:', '["Tap your horn lightly to let them know a car is approaching", "Slow down to 10 mph and maneuver around them cautiously", "Come to a complete stop and yield the right-of-way, regardless of the traffic signal", "Roll down your window and offer verbal directions on when to cross safely"]'::jsonb, 2, 'Drivers must always yield the right-of-way and come to a complete stop for totally or partially blind pedestrians using a guide dog or carrying a white cane, even if the driver has a green light.', 'pedestrian_safety', 'easy', 'drivesight-fl-11', true),
  ('FL', 'When passing a slower-moving vehicle on a two-lane, two-way Florida highway, you must safely return to the right side of the road before an oncoming vehicle comes within:', '["50 feet of your vehicle", "100 feet of your vehicle", "200 feet of your vehicle", "500 feet of your vehicle"]'::jsonb, 2, 'To ensure you do not cause a head-on collision, Florida law dictates that you must complete your pass and return to your designated lane before coming within 200 feet of any approaching oncoming vehicle.', 'passing_rules', 'hard', 'drivesight-fl-11', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('GA', 'Under Georgia''s ''Super Speeder'' law, a driver will face an additional $200 state fee and potential license suspension if convicted of driving at or above what speed on a two-lane road?', '["65 mph", "75 mph", "80 mph", "85 mph"]'::jsonb, 1, 'Georgia''s Super Speeder law triggers an extra $200 state fee for drivers convicted of traveling 75 mph or faster on any two-lane road, or 85 mph or faster on any road or highway in the state.', 'speed_limits', 'hard', 'drivesight-ga-12', true),
  ('GA', 'According to the Hands-Free Georgia Act, which of the following actions is legally permitted while driving a motor vehicle?', '["Holding a phone to send a quick text message while stopped at a red light", "Holding a phone to your ear, provided you are only speaking and not typing", "Using a smartphone exclusively via voice commands or a Bluetooth hands-free earpiece", "Resting the phone on your lap to watch a video while in heavy highway traffic"]'::jsonb, 2, 'The Hands-Free Georgia Act strictly prohibits drivers from having a phone in their hand or supporting it with any part of their body. You may only use a phone via earpiece, wireless, or voice-command technology.', 'distracted_driving', 'easy', 'drivesight-ga-12', true),
  ('GA', 'Georgia''s Move Over Law dictates that when approaching a stationary emergency vehicle with flashing lights on a highway, if moving over a lane is unsafe or impossible due to traffic, a driver must:', '["Maintain the posted speed limit but activate their hazard lights", "Reduce speed below the posted speed limit and be prepared to stop", "Stop completely in their current travel lane until given permission to proceed", "Honk their horn repeatedly while passing closely to warn the workers"]'::jsonb, 1, 'If it is impossible or unsafe to change lanes away from a stationary emergency vehicle in Georgia, you must reduce your speed below the posted speed limit and be prepared to stop if necessary.', 'emergency_vehicles', 'medium', 'drivesight-ga-12', true),
  ('GA', 'In Georgia, it is illegal to drive across, park in, or back up through the ''gore'' area of a highway. What specifically defines the gore area?', '["The unpaved grassy median separating opposing directions of interstate traffic", "The designated emergency pull-off zone located on steep mountain grades", "The far-left High Occupancy Vehicle (HOV) lane during restricted rush hours", "The painted triangular safety zone situated between a highway travel lane and an exit or entrance ramp"]'::jsonb, 3, 'The gore is the converging area bordered by solid white lines where an entrance or exit ramp meets the main highway. Driving across this painted triangular area is illegal and highly dangerous.', 'freeway_driving', 'medium', 'drivesight-ga-12', true),
  ('GA', 'Under what specific circumstance is it legally permissible to make a left turn at a solid red traffic light in Georgia?', '["Whenever the intersection is clear of cross traffic for at least 500 feet", "Only between the hours of Midnight and 5:00 AM", "Only when turning from a one-way street onto another one-way street, after coming to a complete stop", "Never; left turns on red are strictly prohibited statewide"]'::jsonb, 2, 'In Georgia, you may legally turn left on a solid red light only if you are turning from a one-way street onto another one-way street, provided there is no sign prohibiting it and you have made a full stop.', 'traffic_signals', 'hard', 'drivesight-ga-12', true),
  ('GA', 'When overtaking and passing a bicyclist traveling in the same direction on a Georgia road, state law mandates that a motor vehicle driver must leave a minimum safe passing distance of:', '["1 foot", "2 feet", "3 feet", "An entire traffic lane width"]'::jsonb, 2, 'Georgia''s safe passing law requires that drivers must give bicycles at least 3 feet of physical clearance when passing to prevent sideswipes and allow the cyclist room to maneuver around road hazards.', 'passing_rules', 'easy', 'drivesight-ga-12', true),
  ('GA', 'Georgia''s ''Implied Consent'' Law dictates that by operating a motor vehicle on state roads, you automatically agree to:', '["Allow police officers to search your vehicle''s trunk without a warrant during any traffic stop", "Submit to state-administered chemical tests of your blood, breath, or urine if arrested for DUI", "Carry full-coverage auto insurance instead of standard minimum liability", "Plead guilty to any moving violation cited by a State Trooper"]'::jsonb, 1, 'The Implied Consent law means that if you are lawfully arrested by an officer who suspects you of DUI, you have implicitly consented to take a chemical test of your breath, blood, or urine to determine impairment.', 'dui_alcohol_laws', 'medium', 'drivesight-ga-12', true),
  ('GA', 'A school bus has stopped on a two-lane, undivided Georgia road and is displaying its flashing red lights and an extended stop arm. You are traveling in the opposite direction. What is your legal requirement?', '["Slow down to 10 mph and pass the bus with extreme caution", "Stop your vehicle completely and remain stopped until the red lights cease flashing and the stop arm is retracted", "You are not required to stop because you are in the opposing travel lane", "Flash your high beams to warn crossing children and maintain your speed"]'::jsonb, 1, 'On a two-lane undivided highway, all traffic traveling in both directions must come to a complete stop for a school bus with flashing red lights and an extended stop arm to protect crossing children.', 'school_zones', 'easy', 'drivesight-ga-12', true),
  ('GA', 'When entering a Georgia interstate highway from an acceleration lane, who legally possesses the right-of-way?', '["The vehicle attempting to merge onto the interstate from the ramp", "Vehicles already traveling on the interstate highway", "Whichever vehicle is currently traveling at a faster rate of speed", "Commercial semi-trucks only; all passenger vehicles must yield to each other"]'::jsonb, 1, 'Vehicles currently traveling on the interstate highway have the right-of-way. The driver merging from the acceleration lane must adjust their speed and yield to find a safe gap in traffic.', 'merging', 'medium', 'drivesight-ga-12', true),
  ('GA', 'A flashing red traffic signal at a Georgia intersection must be treated legally identically to a:', '["Yield sign", "Stop sign", "Green light, assuming no cross traffic is present", "Pedestrian crosswalk warning"]'::jsonb, 1, 'A flashing red traffic light has the exact same legal meaning as a stop sign. You must come to a full and complete stop, check for pedestrians and cross traffic, and proceed only when it is safe.', 'traffic_signals', 'easy', 'drivesight-ga-12', true),
  ('GA', 'When approaching a railroad crossing in Georgia with lowered warning gates and active flashing lights, you are required to stop your vehicle within what specific distance from the nearest rail?', '["No closer than 5 feet and no further than 10 feet", "No closer than 15 feet and no further than 50 feet", "At least 100 feet away", "Only if you can physically see the train approaching the intersection"]'::jsonb, 1, 'Georgia law dictates that whenever a train is approaching and warning signals are active, a driver must stop their vehicle between 15 and 50 feet from the nearest rail of the railroad crossing.', 'railroad_crossings', 'hard', 'drivesight-ga-12', true),
  ('GA', 'To maximize visibility during inclement weather, Georgia law strictly requires drivers to activate their headlights during which of the following periods?', '["From a half-hour after sunset to a half-hour before sunrise, or when it is raining", "Only when driving on rural county roads without streetlights", "Between the hours of 8:00 PM and 5:00 AM regardless of the season", "Whenever the vehicle is traveling faster than 55 mph on the interstate"]'::jsonb, 0, 'You must use your headlights from a half-hour after sunset to a half-hour before sunrise, when it is raining, or whenever visibility is limited to less than 500 feet.', 'weather_driving', 'medium', 'drivesight-ga-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('HI', 'Under Hawaii''s distracted driving laws, which of the following is legally permitted while operating a motor vehicle on public roads?', '["Reading text messages as long as you do not type a reply", "Using a handheld cell phone only while stopped at a red traffic light", "Using a mobile electronic device exclusively via a hands-free system", "Holding a phone to use its GPS navigation system"]'::jsonb, 2, 'Hawaii enforces a strict hands-free law. It is completely illegal to hold or operate a mobile electronic device with your hands while driving, even when temporarily stopped at a red light or stop sign.', 'distracted_driving', 'easy', 'drivesight-hi-12', true),
  ('HI', 'You are traveling on a multi-lane Hawaii highway divided by a physical concrete median. A school bus traveling in the opposite direction stops and extends its red flashing lights. What must you do?', '["Come to a complete stop and wait for the bus to retract its stop arm", "Slow to 15 mph and proceed with extreme caution", "You may continue driving without stopping because of the physical median", "Honk your horn to warn pedestrians but maintain your speed"]'::jsonb, 2, 'In Hawaii, if a highway is divided by an intervening space or a physical barrier (like a concrete median), vehicles traveling in the opposite direction of a stopped school bus are not required to stop.', 'school_zones', 'medium', 'drivesight-hi-12', true),
  ('HI', 'Hawaii''s ''Zero Tolerance'' law for underage drinking and driving means that a driver under the age of 21 can face license suspension for a Blood Alcohol Concentration (BAC) of:', '["0.08% or higher", "0.05% or higher", "0.02% or higher", "0.10% or higher"]'::jsonb, 2, 'Hawaii enforces a Zero Tolerance law for drivers under 21. Operating a vehicle with a measurable BAC of 0.02% or greater will result in severe penalties, including license suspension.', 'dui_alcohol_laws', 'medium', 'drivesight-hi-12', true),
  ('HI', 'To maximize visibility during dark or hazardous conditions, Hawaii law requires you to turn on your vehicle''s headlights during what specific timeframe?', '["From one hour after sunset until one hour before sunrise", "From a half-hour after sunset to a half-hour before sunrise", "From 8:00 PM to 6:00 AM regardless of the season", "Only when streetlights are not present on the roadway"]'::jsonb, 1, 'State law mandates that headlights must be activated from 30 minutes after sunset until 30 minutes before sunrise, or at any other time when visibility is reduced to less than 500 feet.', 'weather_driving', 'easy', 'drivesight-hi-12', true),
  ('HI', 'You approach an uncontrolled four-way intersection at the same time as a vehicle directly across from you. You intend to turn left, while the other vehicle is traveling straight through. Who has the right-of-way?', '["You have the right-of-way because you are turning", "The vehicle traveling straight has the right-of-way", "The vehicle that is traveling at a higher rate of speed", "Whichever vehicle is larger and heavier"]'::jsonb, 1, 'When two vehicles approach an intersection from opposite directions at the same time, a driver turning left must always yield the right-of-way to the vehicle traveling straight through.', 'right_of_way', 'medium', 'drivesight-hi-12', true),
  ('HI', 'When parallel parking your vehicle facing downhill on a street in Honolulu that has a raised curb, how should you position your front wheels?', '["Keep them straight parallel to the roadway", "Turn them sharply to the right, toward the curb", "Turn them sharply to the left, toward the center of the road", "Rest the tires directly on top of the curb"]'::jsonb, 1, 'When parked facing downhill next to a curb, you should always turn your front wheels sharply toward the right (toward the curb). If your brakes fail, the vehicle will roll into the curb and stop.', 'parking', 'easy', 'drivesight-hi-12', true),
  ('HI', 'A solid yellow line next to a broken yellow line running down the center of a two-way Hawaii roadway indicates that passing is:', '["Prohibited for both directions of traffic", "Permitted only for the side with the solid yellow line", "Permitted only for the side with the broken yellow line", "Permitted during daylight hours for both sides"]'::jsonb, 2, 'A solid yellow line paired with a broken yellow line means that vehicles traveling adjacent to the broken line are permitted to cross it to pass, while vehicles on the solid line side are prohibited from passing.', 'lane_changes', 'easy', 'drivesight-hi-12', true),
  ('HI', 'If you approach a crosswalk and notice a pedestrian who is completely or partially blind, identified by carrying a white cane or using a guide dog, what must you do?', '["Honk your horn to warn them before driving around them", "Yield the right-of-way and come to a full stop until they have crossed", "Slow down to 10 mph and proceed with extreme caution", "Roll down your window and give verbal directions to the pedestrian"]'::jsonb, 1, 'Hawaii drivers must always yield the right-of-way and come to a complete stop for pedestrians carrying a white cane or using a guide dog, regardless of traffic signals or crosswalk markings.', 'pedestrian_safety', 'easy', 'drivesight-hi-12', true),
  ('HI', 'When approaching an intersection displaying a flashing red traffic light, Hawaii drivers must treat it legally the same as:', '["A yield sign", "A standard stop sign", "A pedestrian crossing zone warning", "A flashing yellow light"]'::jsonb, 1, 'A flashing red traffic signal carries the identical legal requirement as a stop sign. You must come to a complete stop behind the limit line, yield to traffic, and proceed only when safe.', 'traffic_signals', 'easy', 'drivesight-hi-12', true),
  ('HI', 'While traveling on the H-1 freeway, you realize you have just missed your intended exit. Your safest and legal action is to:', '["Carefully back up along the right shoulder with your hazard lights flashing", "Stop in the right lane and wait for an opening to reverse", "Continue driving to the next available exit and safely turn around", "Make a U-turn through the grassy median separating the highway"]'::jsonb, 2, 'Backing up or making U-turns on an interstate freeway is extremely dangerous and strictly illegal. If you miss your exit, you must always proceed to the next available exit.', 'freeway_driving', 'easy', 'drivesight-hi-12', true),
  ('HI', 'When preparing to merge onto a Hawaii freeway from an acceleration lane, who holds the legal right-of-way?', '["The vehicle attempting to merge from the entrance ramp", "The vehicles currently traveling on the freeway", "The larger of the two interacting vehicles", "Vehicles traveling in the far-left passing lane"]'::jsonb, 1, 'Drivers entering a freeway from an acceleration lane must yield the right-of-way to vehicles already traveling on the mainline of the freeway.', 'merging', 'medium', 'drivesight-hi-12', true),
  ('HI', 'To maintain a safe following distance behind the vehicle ahead of you under normal driving conditions, the Hawaii Driver''s Manual recommends using the:', '["One car length for every 10 mph rule", "Three-second rule", "Two-second rule", "Five-second rule"]'::jsonb, 1, 'Hawaii recommends the three-second rule to maintain a safe following distance under ideal conditions. You should increase this distance during bad weather or when following motorcycles.', 'defensive_driving', 'easy', 'drivesight-hi-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('ID', 'Under a unique Idaho law, a driver of a passenger car may legally exceed the posted speed limit by up to 15 mph to safely pass a slower-moving vehicle under which specific condition?', '["On a four-lane divided interstate highway", "When passing a semi-truck on a steep uphill grade", "On a two-lane roadway with a posted speed limit of 55 mph or greater", "When passing a slow-moving agricultural tractor in a school zone"]'::jsonb, 2, 'Idaho law uniquely allows passenger vehicles and motorcycles to temporarily exceed the speed limit by up to 15 mph to safely complete a pass, but only on two-lane roads with a posted speed limit of 55 mph or greater.', 'passing_rules', 'hard', 'drivesight-id-12', true),
  ('ID', 'Unless otherwise posted, what is the maximum statutory speed limit on designated rural interstate highways in Idaho?', '["65 mph", "70 mph", "75 mph", "80 mph"]'::jsonb, 3, 'Idaho is one of the few states where the maximum lawful speed limit on designated stretches of rural interstate highways can be up to 80 mph, unless otherwise posted.', 'speed_limits', 'medium', 'drivesight-id-12', true),
  ('ID', 'Idaho''s ''Basic Rule'' regarding driving speeds means that regardless of the officially posted speed limit, you must always:', '["Drive at exactly the posted speed limit at all times", "Drive at a speed that is reasonable and prudent for the current road and weather conditions", "Drive at least 5 mph below the speed limit to avoid a citation", "Keep pace with the flow of traffic even if it exceeds the posted limit"]'::jsonb, 1, 'The Basic Rule requires drivers to operate their vehicle at a speed that is reasonable and prudent for the actual physical conditions of the road, regardless of what the posted speed limit sign says.', 'defensive_driving', 'easy', 'drivesight-id-12', true),
  ('ID', 'When approaching a stationary emergency vehicle displaying flashing lights on a multi-lane Idaho highway, the Move Over law requires you to:', '["Honk your horn continuously to ensure workers see you", "Stop completely in your lane and wait for directions", "Move over one lane away from the vehicle, or slow down below the posted speed limit if shifting lanes is impossible", "Accelerate quickly to clear the hazardous area"]'::jsonb, 2, 'Idaho''s Move Over law requires drivers approaching stationary police, fire, or tow vehicles with flashing lights to move to an adjacent lane, or significantly reduce their speed if shifting lanes is unsafe.', 'emergency_vehicles', 'medium', 'drivesight-id-12', true),
  ('ID', 'You are driving on a rural Idaho highway when heavy snow begins to fall and stick to the pavement. How should you adjust your recommended following distance behind other vehicles?', '["Decrease it to 2 seconds to utilize the tire tracks of the vehicle ahead", "Maintain the standard 3-second rule", "Increase it to 5 seconds", "Increase it to a minimum of 8 to 10 seconds"]'::jsonb, 3, 'Stopping distances increase drastically on snow and ice. The Idaho Driver''s Manual recommends increasing your following distance from the standard 3 seconds to at least 8 to 10 seconds in winter weather conditions.', 'weather_driving', 'medium', 'drivesight-id-12', true),
  ('ID', 'When preparing to enter a multi-lane roundabout intersection in Idaho, who legally holds the right-of-way?', '["The larger, heavier vehicle", "Vehicles attempting to enter the roundabout from your right", "Vehicles already circulating inside the roundabout", "The vehicle moving at the fastest speed"]'::jsonb, 2, 'Drivers entering a roundabout must yield the right-of-way to vehicles, bicyclists, and pedestrians already actively circulating inside the intersection.', 'intersections', 'easy', 'drivesight-id-12', true),
  ('ID', 'Under Idaho''s Zero Tolerance law, a driver under the age of 21 will face severe penalties if arrested for driving with a Blood Alcohol Concentration (BAC) equal to or greater than:', '["0.02%", "0.04%", "0.06%", "0.08%"]'::jsonb, 0, 'Idaho enforces a strict Zero Tolerance policy for underage drinking. If a driver under 21 operates a motor vehicle with a BAC of 0.02% or higher, they will be charged with a DUI.', 'dui_alcohol_laws', 'medium', 'drivesight-id-12', true),
  ('ID', 'While traveling on an Idaho interstate highway, you notice a paved crossover path located in the grassy median separating opposing traffic lanes. Who is legally permitted to use this crossover?', '["Any vehicle wishing to make a U-turn during daylight hours", "Only drivers who have missed an exit and need to turn around", "Only authorized emergency and highway maintenance vehicles", "Any vehicle if traffic in the opposing lane is completely clear"]'::jsonb, 2, 'Median crossovers on interstate highways are strictly reserved for use by emergency responders and authorized highway maintenance vehicles. It is illegal for private motorists to use them to change directions.', 'freeway_driving', 'easy', 'drivesight-id-12', true),
  ('ID', 'You are parking your vehicle facing uphill on a mountain road in Idaho that does not have a physical curb. To prevent rolling into traffic, your front wheels should be turned:', '["Sharply to the left, toward the center of the road", "Sharply to the right, toward the edge of the road or shoulder", "Perfectly straight", "Slightly to the left"]'::jsonb, 1, 'When parking uphill without a curb, always turn your front wheels to the right (toward the shoulder). If the brakes fail, the vehicle will roll off the road into the dirt, not backward into traffic.', 'parking', 'medium', 'drivesight-id-12', true),
  ('ID', 'You approach an intersection with a solid green traffic light and intend to make a left turn. There is no green left-turn arrow illuminated. What is your legal obligation?', '["Turn immediately; the solid green light gives you the right-of-way", "Yield to oncoming traffic and pedestrians, turning only when the intersection is clear", "Pull fully into the intersection and wait for the light to turn red before turning", "Stop completely behind the limit line before proceeding with the turn"]'::jsonb, 1, 'A solid green light means you can proceed, but you do not have a protected turn. You must yield the right-of-way to all oncoming traffic and pedestrians before completing a left turn.', 'traffic_signals', 'easy', 'drivesight-id-12', true),
  ('ID', 'According to Idaho''s distracted driving laws, the act of manually typing or reading a text message while operating a motor vehicle on public roads is:', '["Permitted only when stopped at a red traffic light", "Illegal only for drivers under the age of 18", "Strictly illegal for all drivers, regardless of age", "Permitted if the phone is held below the steering wheel out of view"]'::jsonb, 2, 'Idaho law prohibits all drivers from writing, sending, or reading text-based communications while operating a moving motor vehicle on any public road.', 'distracted_driving', 'easy', 'drivesight-id-12', true),
  ('ID', 'You are driving on a four-lane Idaho road (two lanes traveling in each direction) separated only by a double yellow line. A school bus traveling in the opposite direction stops with its red lights flashing. Must you stop?', '["Yes, all traffic in both directions must stop for a school bus on an undivided road", "No, only traffic traveling in the same direction as the bus must stop on roads with four or more lanes", "Yes, but you may roll past the bus at 10 mph if no children are visible", "No, because the double yellow line acts as a legal physical barrier"]'::jsonb, 1, 'In Idaho, if a roadway has four or more lanes, only traffic traveling in the same direction as the stopped school bus is required to stop. Traffic in the opposite lanes may proceed with caution.', 'school_zones', 'hard', 'drivesight-id-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('IL', 'Under Illinois'' ''Scott''s Law'' (the Move Over Law), what must you do when approaching any stationary vehicle displaying flashing lights on the side of a multi-lane highway?', '["Honk your horn to let the driver know you are passing", "Maintain your speed but turn on your hazard lights", "Reduce your speed significantly and change lanes away from the stationary vehicle if it is safe to do so", "Come to a complete stop and wait for a police officer to wave you around"]'::jsonb, 2, 'Scott''s Law in Illinois requires drivers approaching ANY stationary vehicle with flashing hazard lights (including passenger cars, tow trucks, and police) to slow down, proceed with caution, and change lanes away from the vehicle if possible.', 'emergency_vehicles', 'medium', 'drivesight-il-12', true),
  ('IL', 'Unless otherwise posted, what is the strict maximum speed limit in an Illinois school zone on school days between the hours of 7:00 a.m. and 4:00 p.m. when children are present?', '["15 mph", "20 mph", "25 mph", "30 mph"]'::jsonb, 1, 'In Illinois, the mandated speed limit in a designated school zone is 20 miles per hour on school days when children are actively present. Fines for violating this are severely increased.', 'school_zones', 'easy', 'drivesight-il-12', true),
  ('IL', 'You are driving on a four-lane Illinois highway (two lanes in each direction) separated only by a painted double yellow line. A school bus traveling in the opposite direction stops and extends its red flashing lights. What is your legal obligation?', '["Stop immediately; all traffic on undivided highways must stop", "Slow down to 10 mph and pass cautiously", "You are not required to stop if you are traveling in the opposite direction on a road with four or more lanes", "Stop only if the crossing arm physically blocks your travel lane"]'::jsonb, 2, 'In Illinois, if you are traveling on a highway with four or more lanes, you do not need to stop for a school bus traveling in the opposite direction, even if the road is undivided. Only traffic behind the bus must stop.', 'school_zones', 'hard', 'drivesight-il-12', true),
  ('IL', 'Illinois enforces a ''Zero Tolerance'' law regarding underage drinking and driving. If a driver under the age of 21 is stopped and tests positive for any trace of alcohol in their system, their license will be automatically suspended for a minimum of:', '["30 days", "3 months", "6 months", "1 year"]'::jsonb, 2, 'Under the Zero Tolerance Law, if a driver under 21 is caught with any trace of alcohol in their system, their driving privileges will automatically be suspended for a minimum of 6 months for a first offense.', 'dui_alcohol_laws', 'hard', 'drivesight-il-12', true),
  ('IL', 'According to the Illinois distracted driving laws, under what condition is it legally permissible for a driver of any age to text while driving?', '["Only when stopped at a solid red traffic light", "Only when utilizing voice-activated, hands-free technology", "If the phone is kept below the dashboard out of the driver''s direct line of sight", "Never, texting is universally banned even with voice commands"]'::jsonb, 1, 'Illinois law strictly prohibits the use of hand-held cell phones, texting, or using other electronic communications while operating a motor vehicle. You may only text if you are using voice-activated, entirely hands-free technology.', 'distracted_driving', 'medium', 'drivesight-il-12', true),
  ('IL', 'When preparing to execute a legal left turn on a solid red light in Illinois, you must first come to a complete stop and yield. Under what specific condition is this turn allowed?', '["When turning from a two-way street onto another two-way street", "When turning from a one-way street onto another one-way street", "When turning from a two-way street onto a one-way street", "Whenever the intersection is completely clear of cross traffic"]'::jsonb, 1, 'In Illinois, turning left on a solid red light is highly restricted. It is only legal when you are turning from a one-way street directly onto another one-way street that has traffic moving to the left.', 'traffic_signals', 'medium', 'drivesight-il-12', true),
  ('IL', 'When passing a bicyclist who is traveling in the same direction on an Illinois road, state law dictates that a motor vehicle must leave a minimum physical clearance of at least:', '["2 feet", "3 feet", "4 feet", "5 feet"]'::jsonb, 1, 'Illinois'' safe passing law requires drivers to provide a minimum of 3 feet of space when passing a bicyclist, and the driver must not return to the right side of the lane until safely clear.', 'passing_rules', 'easy', 'drivesight-il-12', true),
  ('IL', 'To increase visibility and safety during inclement weather, Illinois state law requires that you turn on your vehicle''s headlights whenever:', '["You are traveling on an interstate highway", "The temperature falls below freezing", "You must use your windshield wipers due to rain, snow, or fog", "You enter a marked construction or work zone"]'::jsonb, 2, 'Illinois law explicitly mandates that a driver must turn on their headlights any time atmospheric conditions require the use of their windshield wipers to maintain visibility.', 'weather_driving', 'easy', 'drivesight-il-12', true),
  ('IL', 'You are parking your vehicle facing uphill on a steep street in Chicago that features a prominent concrete curb. To secure your vehicle against rolling into traffic, your front wheels should be turned:', '["Sharply to the left, away from the curb", "Sharply to the right, toward the curb", "Parallel to the centerline of the roadway", "Directly onto the sidewalk"]'::jsonb, 0, 'When parking uphill with a curb, turn your front wheels sharply away from the curb. This ensures that if the vehicle begins to roll backward, the back of the front tire will hit the curb and stop the car.', 'parking', 'medium', 'drivesight-il-12', true),
  ('IL', 'At a four-way stop intersection in Illinois, three vehicles arrive simultaneously. Which vehicle legally holds the right-of-way?', '["The vehicle traveling at the fastest speed", "The vehicle making a left-hand turn", "The vehicle positioned furthest to the right", "The vehicle making a right-hand turn"]'::jsonb, 2, 'At an intersection controlled by four-way stop signs where multiple vehicles arrive at the same time, the driver of the vehicle on the left must yield the right-of-way to the vehicle on the immediate right.', 'right_of_way', 'easy', 'drivesight-il-12', true),
  ('IL', 'If you approach a railroad crossing in Illinois that does not have warning lights or lowered crossing gates, what is your safest and legal course of action?', '["Accelerate to clear the tracks as quickly as possible", "Slow down, look in both directions along the tracks, and listen for an approaching train before crossing", "Stop completely at the tracks regardless of whether a train is visible", "Shift gears manually while crossing the tracks"]'::jsonb, 1, 'At passive railroad crossings (those without active gates or flashing lights), it is the driver''s responsibility to slow down, look both ways, and listen carefully for a train before proceeding across the tracks.', 'railroad_crossings', 'easy', 'drivesight-il-12', true),
  ('IL', 'When entering an Illinois interstate from an acceleration lane, your primary responsibility to ensure a safe merge is to:', '["Come to a full stop at the end of the ramp and wait for an opening", "Drive down the shoulder until traffic slows down enough to let you in", "Adjust your speed to match the flow of highway traffic and yield to vehicles already on the interstate", "Signal continuously, forcing drivers in the right lane to move to the left lane"]'::jsonb, 2, 'Drivers entering a highway from an acceleration lane must yield the right-of-way to vehicles already traveling on the mainline. You must adjust your speed to find a safe gap in the traffic flow.', 'merging', 'medium', 'drivesight-il-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
insert into public.driving_test_questions (state_code, prompt, choices, answer_index, explanation, category, difficulty, source, is_active)
values
  ('IN', 'Indiana''s Move Over Law applies to stationary emergency, maintenance, and utility vehicles displaying flashing lights. If you cannot safely change lanes to move away from the vehicle, you must:', '["Stop completely until an officer directs you to proceed", "Maintain your speed but turn on your hazard lights", "Reduce your speed to at least 10 mph below the posted speed limit and proceed with caution", "Accelerate quickly to clear the hazard zone"]'::jsonb, 2, 'If it is impossible or unsafe to change lanes away from a stationary emergency or recovery vehicle in Indiana, the law requires you to slow down to at least 10 mph below the posted speed limit and proceed with caution.', 'emergency_vehicles', 'medium', 'drivesight-in-12', true),
  ('IN', 'Under Indiana law, what is the maximum statutory speed limit on a rural interstate highway unless otherwise posted?', '["60 mph", "65 mph", "70 mph", "75 mph"]'::jsonb, 2, 'In Indiana, passenger vehicles may travel at a maximum speed of 70 mph on rural interstate highways, provided weather and traffic conditions allow for safe driving at that speed.', 'speed_limits', 'medium', 'drivesight-in-12', true),
  ('IN', 'A school bus has stopped on an undivided, two-lane road in Indiana and activated its flashing red lights. You are traveling in the opposite direction. Are you required to stop?', '["Yes, all traffic traveling in both directions must stop", "No, only vehicles traveling in the same direction as the bus must stop", "Yes, but you may proceed at 10 mph after yielding to children", "No, unless a crossing guard is physically standing in the roadway"]'::jsonb, 0, 'On a two-lane undivided roadway, Indiana law requires that all vehicles traveling in both directions must come to a complete stop for a school bus displaying its flashing red lights.', 'school_zones', 'easy', 'drivesight-in-12', true),
  ('IN', 'For drivers under the age of 18 in Indiana, what are the legal restrictions regarding the use of telecommunications devices while driving?', '["They may use a cell phone only if it is completely hands-free", "They may text only when stopped at a red light", "They are strictly prohibited from using any telecommunications device, including hands-free, except to call 911", "They may use a handheld phone for phone calls but not for texting"]'::jsonb, 2, 'Drivers under 18 in Indiana are banned from using any type of telecommunications device while driving, even if the device is hands-free or Bluetooth enabled, unless they are making a genuine emergency 911 call.', 'distracted_driving', 'medium', 'drivesight-in-12', true),
  ('IN', 'To maintain a safe following distance under ideal driving conditions, the Indiana Driver''s Manual recommends drivers follow the:', '["One car length per 10 mph rule", "Two to three-second rule", "Five-second rule", "100-foot constant distance rule"]'::jsonb, 1, 'Indiana recommends using the two to three-second rule to maintain a safe following distance under normal, dry driving conditions. This distance should be increased during bad weather or when following large trucks.', 'defensive_driving', 'easy', 'drivesight-in-12', true),
  ('IN', 'When preparing to make a right turn at an intersection with a solid red traffic light in Indiana, what is the proper legal procedure?', '["Slow down, look both ways, and turn without fully stopping if the road is clear", "Come to a full and complete stop, yield the right-of-way to pedestrians and oncoming traffic, then proceed when safe", "Wait for the pedestrian countdown timer to end, then turn", "You cannot turn right on a solid red light in Indiana under any circumstances"]'::jsonb, 1, 'Unless specifically prohibited by a sign, you may make a right turn on red in Indiana, but you must first bring your vehicle to a full and complete stop and yield to all cross traffic and pedestrians.', 'traffic_signals', 'easy', 'drivesight-in-12', true),
  ('IN', 'When approaching a railroad crossing where active red lights are flashing, Indiana law requires you to stop your vehicle within what distance of the nearest rail?', '["No closer than 15 feet and no further than 50 feet", "No closer than 5 feet and no further than 20 feet", "Exactly 30 feet away", "Only if the physical crossing gate is fully lowered across your lane"]'::jsonb, 0, 'When a train is approaching and railroad crossing signals are active, Indiana state law dictates that a driver must come to a complete stop between 15 and 50 feet from the nearest rail.', 'railroad_crossings', 'hard', 'drivesight-in-12', true),
  ('IN', 'You are driving on a multi-lane highway in Indiana and wish to pass a large commercial semi-truck. Why should you avoid lingering in the lanes directly beside the truck?', '["Semi-trucks create a vacuum that can pull your car into their lane", "The areas directly beside a semi-truck are large blind spots known as ''No-Zones''", "Truck drivers are required by law to change lanes frequently", "You are required to honk your horn continuously when beside a commercial vehicle"]'::jsonb, 1, 'Commercial trucks have extensive blind spots on both sides, the immediate rear, and the front. These are called ''No-Zones.'' If you linger in these areas, the truck driver cannot see you, making a collision highly likely.', 'defensive_driving', 'easy', 'drivesight-in-12', true),
  ('IN', 'If your vehicle begins to hydroplane on a wet Indiana roadway during a heavy rainstorm, what is the safest way to regain control of the vehicle?', '["Slam on the brakes to force the tires back onto the pavement", "Jerk the steering wheel sharply in the opposite direction of the skid", "Ease your foot off the accelerator pedal and steer straight until the tires regain traction", "Accelerate quickly to push the water out from beneath the tires"]'::jsonb, 2, 'During a hydroplane, sudden braking or steering can cause a total loss of control. The best action is to take your foot off the gas and keep the wheel straight, allowing the vehicle to slow naturally until the tires reconnect with the road.', 'weather_driving', 'medium', 'drivesight-in-12', true),
  ('IN', 'In Indiana, state law considers a non-commercial driver over the age of 21 to be legally intoxicated and subject to a DUI arrest if their Blood Alcohol Concentration (BAC) reaches or exceeds:', '["0.04%", "0.05%", "0.08%", "0.10%"]'::jsonb, 2, 'For standard drivers aged 21 and older in Indiana, driving with a BAC of 0.08% or higher constitutes driving under the influence and will result in criminal charges and license suspension.', 'dui_alcohol_laws', 'easy', 'drivesight-in-12', true),
  ('IN', 'When preparing to enter an Indiana roundabout intersection, which traffic legally holds the right-of-way?', '["Traffic that is attempting to enter the roundabout from the right", "Traffic that is already actively circulating inside the roundabout", "Whichever vehicle arrives at the intersection first", "Traffic attempting to exit the roundabout"]'::jsonb, 1, 'Drivers attempting to enter a roundabout must always yield the right-of-way to vehicles, bicyclists, and pedestrians that are already circulating within the traffic circle.', 'intersections', 'easy', 'drivesight-in-12', true),
  ('IN', 'A solid double yellow line running down the center of an Indiana roadway indicates that:', '["Passing is strictly prohibited for traffic traveling in both directions", "Passing is allowed if the vehicle ahead is moving significantly below the speed limit", "The road is transitioning into a one-way street", "The lane is designated for carpool vehicles only"]'::jsonb, 0, 'A solid double yellow line separates traffic moving in opposite directions and means that neither lane is legally permitted to cross the centerline to overtake and pass another vehicle.', 'lane_changes', 'easy', 'drivesight-in-12', true);
insert into public.state_driving_tests (state_code, state_name, question_count)
